/* ==========================================================================
   VISTAARA HACKATHON STYLES & DECORATIONS (From reference.html)
   ========================================================================== */

/* Corner bracket decoration */
.bracket {
  position: relative;
}
.bracket::before,
.bracket::after {
  content: "";
  position: absolute;
  width: 18px;
  height: 18px;
  border-color: var(--amber);
  border-style: solid;
  border-width: 0;
  pointer-events: none;
}
.bracket::before {
  top: -1px; left: -1px;
  border-top-width: 2.5px;
  border-left-width: 2.5px;
}
.bracket::after {
  bottom: -1px; right: -1px;
  border-bottom-width: 2.5px;
  border-right-width: 2.5px;
}

/* Hero Schematic Strip (Ages, Participants, Teams, Mentors, Sessions) */
.hero-schematic-strip {
  display: flex;
  flex-wrap: wrap;
  gap: 20px;
  padding-top: 20px;
  margin-top: 22px;
  border-top: 1px dashed rgba(255, 255, 255, 0.2);
}

.hero-schematic-item {
  flex: 1;
  min-width: 120px;
}

.hero-schematic-item .item-num {
  font-family: var(--font-mono);
  font-size: 0.72rem;
  color: var(--energy-cyan);
  text-transform: uppercase;
  letter-spacing: 0.06em;
}

.hero-schematic-item .item-val {
  font-family: var(--font-heading);
  font-size: 1.45rem;
  font-weight: 700;
  color: #ffffff;
  margin-top: 2px;
}

/* Pull Note from reference.html */
.pull-note {
  border-left: 3px solid var(--amber);
  padding: 16px 20px;
  background: rgba(255, 183, 3, 0.06);
  border-radius: 0 var(--radius-xs) var(--radius-xs) 0;
  margin: 16px 0;
}

.pull-note .pull-label {
  font-family: var(--font-mono);
  font-size: 0.72rem;
  font-weight: 700;
  color: var(--blueprint);
  text-transform: uppercase;
  letter-spacing: 0.06em;
  margin-bottom: 6px;
}

.pull-note p {
  font-family: var(--font-heading);
  font-size: 1.15rem;
  font-weight: 600;
  line-height: 1.45;
  color: var(--ink);
}

/* Target Themes Block & Grid */
.themes-block {
  margin-top: 40px;
  padding-top: 32px;
  border-top: 1px dashed rgba(30, 58, 115, 0.25);
}

.themes-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(170px, 1fr));
  gap: 12px;
  margin-top: 18px;
}

.theme-card {
  background: #ffffff;
  border: 1.5px solid var(--line-light);
  border-radius: var(--radius-xs);
  padding: 14px 18px;
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: 0.95rem;
  color: var(--blueprint);
  display: flex;
  align-items: center;
  gap: 10px;
  box-shadow: 2px 2px 0px rgba(30, 58, 115, 0.06);
  transition: transform var(--transition-fast), box-shadow var(--transition-fast), border-color var(--transition-fast);
}

.theme-card:hover {
  transform: translateY(-2px);
  border-color: var(--amber);
  box-shadow: 4px 4px 0px var(--amber);
}

.theme-card::before {
  content: "◆";
  color: var(--amber);
  font-size: 11px;
}

