const eyeCanvas = document.createElement('canvas');
eyeCanvas.width = 256;
eyeCanvas.height = 128;
const eyeCtx = eyeCanvas.getContext('2d');
const eyeTexture = new THREE.CanvasTexture(eyeCanvas);

function drawPixelEyes(expression = 'happy') {
  eyeCtx.fillStyle = '#0a1020';
  eyeCtx.fillRect(0, 0, 256, 128);

  // Cyan glowing LED matrix color for Tara
  eyeCtx.fillStyle = '#00D1FF';
  eyeCtx.shadowColor = '#00D1FF';
  eyeCtx.shadowBlur = 12;

  const blockSize = 8;
  const gap = 2;

  function drawPixelBlock(x, y) {
    eyeCtx.fillRect(x * (blockSize + gap) + 32, y * (blockSize + gap) + 36, blockSize, blockSize);
  }

  if (expression === 'happy') {
    // Curved smiling arcs ^  ^
    const leftArc = [
      [2, 3], [3, 2], [4, 1], [5, 1], [6, 2], [7, 3],
      [3, 3], [4, 2], [5, 2], [6, 3]
    ];
    leftArc.forEach(p => drawPixelBlock(p[0], p[1]));
    leftArc.forEach(p => drawPixelBlock(p[0] + 10, p[1]));
  } else if (expression === 'excited') {
    // > < joyful squint
    const leftSquint = [
      [2, 1], [3, 2], [4, 3], [3, 4], [2, 5],
      [3, 1], [4, 2], [5, 3], [4, 4], [3, 5]
    ];
    leftSquint.forEach(p => drawPixelBlock(p[0], p[1]));
    const rightSquint = [
      [17, 1], [16, 2], [15, 3], [16, 4], [17, 5],
      [16, 1], [15, 2], [14, 3], [15, 4], [16, 5]
    ];
    rightSquint.forEach(p => drawPixelBlock(p[0], p[1]));
  } else if (expression === 'focused') {
    // - - sharp builder architecture scan
    for (let x = 2; x <= 8; x++) {
      drawPixelBlock(x, 2);
      drawPixelBlock(x, 3);
      drawPixelBlock(x + 10, 2);
      drawPixelBlock(x + 10, 3);
    }
  } else if (expression === 'cheering') {
    // \o/ wide sparkle eyes
    for (let x = 3; x <= 7; x++) {
      for (let y = 1; y <= 5; y++) {
        drawPixelBlock(x, y);
        drawPixelBlock(x + 9, y);
      }
    }
  } else if (expression === 'curious') {
    // o  . asymmetric
    for (let x = 3; x <= 7; x++) {
      for (let y = 1; y <= 5; y++) {
        drawPixelBlock(x, y);
      }
    }
    drawPixelBlock(13, 3);
    drawPixelBlock(14, 3);
    drawPixelBlock(13, 4);
    drawPixelBlock(14, 4);
  }
  eyeTexture.needsUpdate = true;
}
