    }
  }

  steppers.forEach(btn => {
    btn.addEventListener('click', () => {
      const key = btn.getAttribute('data-key');
      const action = btn.getAttribute('data-action');
      const min = parseInt(btn.getAttribute('data-min'), 10);
      const max = parseInt(btn.getAttribute('data-max'), 10);

      if (state[key] !== undefined) {
        if (action === 'inc' && state[key] < max) {
          state[key]++;
        } else if (action === 'dec' && state[key] > min) {
          state[key]--;
        }

        const valEl = document.getElementById(`val-${key}`);
        if (valEl) valEl.textContent = state[key];

        calculateScore();
        if (soundEnabled) playClickSound();
      }
    });
  });

  presetBtns.forEach(p => {
    p.addEventListener('click', () => {
      const preset = p.getAttribute('data-preset');
      if (preset === 'auto') {
        // Deep Tech & AI Focus
        state.autoNear = 11;
        state.autoFar = 12;
        state.teleNear = 19;
        state.teleFar = 19;
        state.teleSig = 12;
        state.teleHang = 9;
        state.safetyBonus = 4;
      } else if (preset === 'combat') {
        // Product & UX Heavy
        state.autoNear = 14;
        state.autoFar = 13;
        state.teleNear = 16;
        state.teleFar = 15;
        state.teleSig = 15;
        state.teleHang = 9;
        state.safetyBonus = 5;
      } else if (preset === 'max') {
        // Grand Champion Ceiling (Perfect 100)
        state.autoNear = 15;
        state.autoFar = 15;
        state.teleNear = 20;
        state.teleFar = 20;
        state.teleSig = 15;
        state.teleHang = 10;
        state.safetyBonus = 5;
      }

      Object.keys(state).forEach(k => {
        const el = document.getElementById(`val-${k}`);
        if (el) el.textContent = state[k];
      });

      calculateScore();
      if (soundEnabled) playSuccessSound();
    });
  });

  calculateScore();
}

