    document.getElementById('modalStep1'),
    document.getElementById('modalStep2'),
    document.getElementById('modalStep3'),
    document.getElementById('modalStep4')
  ];

  let currentStep = 0;

  function setStep(stepIndex) {
    currentStep = stepIndex;
    steps.forEach((step, idx) => {
      if (step) step.style.display = idx === currentStep ? 'block' : 'none';
    });

    stepPills.forEach((pill, idx) => {
      pill.classList.toggle('active', idx === currentStep);
    });

    if (prevBtn) prevBtn.style.display = currentStep > 0 && currentStep < 3 ? 'inline-flex' : 'none';
    if (nextBtn) nextBtn.style.display = currentStep < 2 ? 'inline-flex' : 'none';
    if (submitBtn) submitBtn.style.display = currentStep === 2 ? 'inline-flex' : 'none';
  }

  function openModal() {
    if (modal) {
      modal.classList.add('active');
      setStep(0);
      if (soundEnabled) playClickSound();
    }
  }

  function closeModal() {
    if (modal) {
      modal.classList.remove('active');
    }
  }

  openBtns.forEach(btn => btn.addEventListener('click', openModal));
  if (closeBtn) closeBtn.addEventListener('click', closeModal);

  if (modal) {
    modal.addEventListener('click', (e) => {
      if (e.target === modal) closeModal();
    });
  }

  if (nextBtn) {
    nextBtn.addEventListener('click', () => {
      if (currentStep < 2) {
        setStep(currentStep + 1);
        if (soundEnabled) playClickSound();
      }
    });
  }

  if (prevBtn) {
    prevBtn.addEventListener('click', () => {
      if (currentStep > 0) {
        setStep(currentStep - 1);
        if (soundEnabled) playClickSound();
      }
    });
  }

  if (submitBtn) {
    submitBtn.addEventListener('click', () => {
      // Transfer values to Digital Pass
      const teamName = document.getElementById('regTeamName')?.value || 'ORBIT BUILDERS';
      const division = document.getElementById('regDivision')?.value || 'App Development Track';
