   ========================================================================== */
function initScoreCalculator() {
  const state = {
    autoNear: 4,
    autoFar: 2,
    autoSig: 1,
    autoHang: 0,
    teleNear: 6,
    teleFar: 4,
    teleSig: 1,
    teleHang: 1,
    safetyBonus: 1
  };

  const steppers = document.querySelectorAll('.stepper-btn');
  const presetBtns = document.querySelectorAll('.preset-chip-btn');

  function calculateScore() {
    // Autonomous: Near=10pts, Far=20pts, Signature=50pts, Hang=70pts
    const autoScore = (state.autoNear * 10) + (state.autoFar * 20) + (state.autoSig * 50) + (state.autoHang * 70);
    // Human Controlled: Near=5pts, Far=10pts, Signature=50pts, Hang=70pts
    const teleScore = (state.teleNear * 5) + (state.teleFar * 10) + (state.teleSig * 50) + (state.teleHang * 70);
    // Safety & rules bonus
    const endgameScore = state.safetyBonus * 20;

    const total = autoScore + teleScore + endgameScore;

    const totalEl = document.getElementById('calcTotalScore');
    const autoEl = document.getElementById('calcAutoScore');
    const teleEl = document.getElementById('calcTeleopScore');
    const endEl = document.getElementById('calcEndgameScore');
    const rankBadge = document.getElementById('calcRankBadge');
    const mascotMsg = document.getElementById('calcMascotMsg');

    if (totalEl) totalEl.textContent = total;
    if (autoEl) autoEl.textContent = autoScore;
