        if (mascotMsg) mascotMsg.textContent = '"INCREDIBLE! 280+ points! You mastered the 50-Pixel Canvas and the 70pt Hang!"';
      } else if (total >= 190) {
        rankBadge.textContent = 'ARENA FINALIST';
        rankBadge.style.background = 'var(--energy-cyan)';
        rankBadge.style.color = '#000';
        if (mascotMsg) mascotMsg.textContent = '"Fantastic autonomous scoring! That 20pt Far Zone distance bonus makes all the difference!"';
      } else if (total >= 110) {
        rankBadge.textContent = 'PLAYOFF SEED';
        rankBadge.style.background = 'var(--alliance-blue)';
        rankBadge.style.color = '#fff';
        if (mascotMsg) mascotMsg.textContent = '"Solid match strategy! Try placing 1 more Signature Pixel for +50 points!"';
      } else {
        rankBadge.textContent = 'QUALIFIER ROOKIE';
        rankBadge.style.background = 'var(--frame-gray)';
        rankBadge.style.color = '#111';
        if (mascotMsg) mascotMsg.textContent = '"Small blocks, big ideas! Dial in your autonomous Far Zone targeting routine!"';
      }
    }
  }

  steppers.forEach(btn => {
    btn.addEventListener('click', () => {
      const key = btn.getAttribute('data-key');
      const action = btn.getAttribute('data-action');
      const min = parseInt(btn.getAttribute('data-min'), 10);
      const max = parseInt(btn.getAttribute('data-max'), 10);

      if (state[key] !== undefined) {
        if (action === 'inc' && state[key] < max) {
          state[key]++;
        } else if (action === 'dec' && state[key] > min) {
          state[key]--;
        }

        const valEl = document.getElementById(`val-${key}`);
        if (valEl) valEl.textContent = state[key];

        calculateScore();
        if (soundEnabled) playClickSound();
      }
    });
  });

  presetBtns.forEach(p => {
    p.addEventListener('click', () => {
      const preset = p.getAttribute('data-preset');
      if (preset === 'auto') {
        // Autonomous Heavy Sniper (Signature + Far + Auto Hang)
        state.autoNear = 2;
        state.autoFar = 6;
        state.autoSig = 2;
        state.autoHang = 1;
        state.teleNear = 4;
        state.teleFar = 2;
        state.teleSig = 0;
        state.teleHang = 1;
        state.safetyBonus = 1;
      } else if (preset === 'combat') {
        // High Volume Tele-Op Cycles
        state.autoNear = 4;
        state.autoFar = 2;
        state.autoSig = 1;
        state.autoHang = 0;
        state.teleNear = 12;
        state.teleFar = 6;
        state.teleSig = 1;
        state.teleHang = 1;
        state.safetyBonus = 1;
      } else if (preset === 'max') {
        // Perfect 50-Pixel Canvas + Dual Hang Ceiling
        state.autoNear = 6;
        state.autoFar = 8;
        state.autoSig = 2;
        state.autoHang = 1;
        state.teleNear = 8;
        state.teleFar = 6;
        state.teleSig = 1;
        state.teleHang = 2;
        state.safetyBonus = 1;
      }

      Object.keys(state).forEach(k => {
        const el = document.getElementById(`val-${k}`);
        if (el) el.textContent = state[k];
      });

      calculateScore();
      if (soundEnabled) playSuccessSound();
    });
  });

  calculateScore();
}

