/* ==========================================================================
   HERO BUILDER TERMINAL & EVENT CONSOLE
   ========================================================================== */
.hero-terminal-card {
  background: #0f1422;
  border: 1.5px solid var(--blueprint);
  border-radius: var(--radius-sm);
  box-shadow: 8px 8px 0px rgba(30, 58, 115, 0.45);
  overflow: hidden;
  display: flex;
  flex-direction: column;
}

.terminal-header {
  background: #161e33;
  padding: 12px 16px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.1);
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.terminal-controls {
  display: flex;
  align-items: center;
  gap: 7px;
}

.terminal-dot {
  width: 9px;
  height: 9px;
  border-radius: 50%;
}
.terminal-dot.dot-red { background: #ff5f56; }
.terminal-dot.dot-yellow { background: #ffbd2e; }
.terminal-dot.dot-green { background: #27c93f; }

.terminal-title {
  font-family: var(--font-mono);
  font-size: 0.74rem;
  font-weight: 700;
  color: var(--amber);
  letter-spacing: 0.04em;
}

.terminal-status-badge {
  font-family: var(--font-mono);
  font-size: 0.65rem;
  color: var(--energy-cyan);
  background: rgba(0, 209, 255, 0.12);
  border: 1px solid rgba(0, 209, 255, 0.3);
  border-radius: 3px;
  padding: 2px 7px;
}

.terminal-body {
  padding: 20px;
  display: flex;
  flex-direction: column;
  gap: 16px;
  color: #e2e8f0;
}

.terminal-metric-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 10px;
}

.terminal-metric-box {
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: var(--radius-xs);
  padding: 12px;
}

.terminal-metric-label {
  font-family: var(--font-mono);
  font-size: 0.66rem;
  color: #94a3b8;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.terminal-metric-val {
  font-family: var(--font-heading);
  font-size: 1.25rem;
  font-weight: 700;
  color: #ffffff;
  margin-top: 3px;
}

.terminal-stage-row {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 6px;
}

.terminal-stage-chip {
  background: rgba(30, 58, 115, 0.25);
  border: 1px solid var(--line);
  border-radius: 4px;
  padding: 8px 6px;
  text-align: center;
}

.terminal-stage-num {
  font-family: var(--font-mono);
  font-size: 0.62rem;
  color: var(--amber);
  font-weight: 700;
}

.terminal-stage-name {
  font-family: var(--font-heading);
  font-size: 0.75rem;
  color: #ffffff;
  font-weight: 600;
  margin-top: 2px;
}

.terminal-code-block {
  background: #090c15;
  border: 1px solid rgba(255, 255, 255, 0.07);
  border-radius: 4px;
  padding: 12px 14px;
  font-family: var(--font-mono);
  font-size: 0.74rem;
