/* ==========================================================================
   FLOATING INTERACTIVE MASCOT COMPANION (Bottom-Right Widget)
   ========================================================================== */
.pixel-floating-companion {
  position: fixed;
  bottom: 24px;
  right: 24px;
  z-index: 9999;
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  pointer-events: none;
}

.pixel-floating-companion > * {
  pointer-events: auto;
}

.companion-bubble {
  background: #ffffff;
  border: 1.5px solid var(--ink);
  box-shadow: 3px 3px 0px var(--ink);
  border-radius: 8px;
  padding: 10px 14px;
  font-size: 0.82rem;
  font-weight: 600;
  color: var(--ink);
  max-width: 240px;
  margin-bottom: 8px;
  opacity: 0;
  transform: translateY(10px) scale(0.95);
  pointer-events: none;
  transition: all 0.25s cubic-bezier(0.16, 1, 0.3, 1);
  position: relative;
  line-height: 1.4;
}

.companion-bubble.show {
  opacity: 1;
  transform: translateY(0) scale(1);
  pointer-events: auto;
}

.companion-bubble::after {
  content: '';
  position: absolute;
  bottom: -7px;
  right: 24px;
  border-width: 7px 7px 0 7px;
  border-style: solid;
  border-color: var(--ink) transparent transparent transparent;
}

.companion-bot-btn {
  width: 58px;
  height: 58px;
  border-radius: 50%;
  background: #ffffff;
  border: 2px solid var(--ink);
  box-shadow: 4px 4px 0px var(--alliance-blue);
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  position: relative;
  transition: transform 0.2s cubic-bezier(0.34, 1.56, 0.64, 1), box-shadow 0.2s ease;
}

