/* ==========================================================================
   4. THREE.JS 3D PIXEL BOT STAGE (Studio Light Aesthetic & Dynamic Expressions)
   ========================================================================== */
let setPixelExpressionGlobal = null;

function initThreeStage() {
  const container = document.getElementById('robot3dCanvas');
  if (!container || typeof THREE === 'undefined') return;

  const scene = new THREE.Scene();
  scene.background = new THREE.Color(0xffffff);

  const camera = new THREE.PerspectiveCamera(40, container.clientWidth / container.clientHeight, 0.1, 100);
  camera.position.set(4.0, 2.5, 4.4);

  const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: false });
  renderer.setSize(container.clientWidth, container.clientHeight);
  renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
  renderer.shadowMap.enabled = true;
  renderer.shadowMap.type = THREE.PCFSoftShadowMap;
  renderer.toneMapping = THREE.ACESFilmicToneMapping;
  container.appendChild(renderer.domElement);

  // Clean Studio Lighting
  const ambientLight = new THREE.AmbientLight(0xffffff, 0.85);
  scene.add(ambientLight);

  const keyLight = new THREE.DirectionalLight(0xffffff, 1.25);
  keyLight.position.set(6, 12, 8);
  keyLight.castShadow = true;
  keyLight.shadow.mapSize.width = 1024;
  keyLight.shadow.mapSize.height = 1024;
  scene.add(keyLight);

  const cyanRim = new THREE.DirectionalLight(0x00d1ff, 0.65);
  cyanRim.position.set(-6, 4, -4);
  scene.add(cyanRim);

  const amberFill = new THREE.DirectionalLight(0xffb703, 0.5);
  amberFill.position.set(5, -2, -3);
  scene.add(amberFill);

  // Ground Grid
  const gridHelper = new THREE.GridHelper(16, 32, 0x1E3A73, 0xe2e8f0);
  gridHelper.position.y = -0.9;
  scene.add(gridHelper);

  // Character Pivot
  const pixelBotGroup = new THREE.Group();
  scene.add(pixelBotGroup);

  // Shared Materials
  let isWireframe = false;
  const whiteArmorMat = new THREE.MeshStandardMaterial({
    color: 0xf8fafc,
    roughness: 0.25,
    metalness: 0.1,
    wireframe: isWireframe
  });

  const darkJointMat = new THREE.MeshStandardMaterial({
    color: 0x12172b,
    roughness: 0.45,
    metalness: 0.6,
    wireframe: isWireframe
  });

  const blueprintMat = new THREE.MeshStandardMaterial({
    color: 0x1E3A73,
    roughness: 0.35,
    metalness: 0.3,
    wireframe: isWireframe
  });

  const amberMat = new THREE.MeshStandardMaterial({
    color: 0xffb703,
    roughness: 0.3,
    metalness: 0.2,
    wireframe: isWireframe
  });

  const amberGlowMat = new THREE.MeshBasicMaterial({
    color: 0xffb703
  });

  const cyanGlowMat = new THREE.MeshBasicMaterial({
    color: 0x00d1ff
  });

  // Dynamic Eye Visor Canvas Texture (Pixel Matrix)
  const visorCanvas = document.createElement('canvas');
  visorCanvas.width = 256;
  visorCanvas.height = 128;
  const vCtx = visorCanvas.getContext('2d');

  function drawPixelEyes(expr = 'happy') {
    vCtx.fillStyle = '#090d1a';
    vCtx.fillRect(0, 0, 256, 128);

    vCtx.fillStyle = '#00D1FF';
    vCtx.shadowColor = '#00D1FF';
    vCtx.shadowBlur = 12;

    const eyeLeftX = 64;
    const eyeRightX = 192;
    const eyeY = 64;

    if (expr === 'happy') {
      // Inverted U curves (smiling eyes)
      [eyeLeftX, eyeRightX].forEach(x => {
        vCtx.fillRect(x - 22, eyeY - 6, 44, 12);
        vCtx.fillRect(x - 28, eyeY, 12, 16);
        vCtx.fillRect(x + 16, eyeY, 12, 16);
      });
    } else if (expr === 'excited') {
      // Big open star eyes
      [eyeLeftX, eyeRightX].forEach(x => {
        vCtx.fillRect(x - 24, eyeY - 24, 48, 48);
        vCtx.fillStyle = '#FFB703';
        vCtx.fillRect(x - 12, eyeY - 12, 24, 24);
        vCtx.fillStyle = '#00D1FF';
      });
    } else if (expr === 'focused') {
      // Narrow tech scan bars
      [eyeLeftX, eyeRightX].forEach(x => {
        vCtx.fillRect(x - 28, eyeY - 4, 56, 8);
        vCtx.fillRect(x - 12, eyeY - 14, 24, 6);
      });
    } else if (expr === 'cheering') {
      // Angular ^ ^ eyes
      [eyeLeftX, eyeRightX].forEach(x => {
        vCtx.fillRect(x - 20, eyeY - 10, 40, 10);
        vCtx.fillRect(x - 26, eyeY, 12, 14);
        vCtx.fillRect(x + 14, eyeY, 14, 14);
      });
    } else if (expr === 'curious') {
      // Asymmetric O _ o
      vCtx.fillRect(eyeLeftX - 18, eyeY - 18, 36, 36);
      vCtx.fillRect(eyeRightX - 22, eyeY - 4, 44, 8);
    }
  }
  drawPixelEyes('happy');

  const visorTexture = new THREE.CanvasTexture(visorCanvas);
  const visorMat = new THREE.MeshBasicMaterial({ map: visorTexture });

  // --------------------------------------------------------------------------
  // Build Tara Mascot Chassis (3D Studio Pixel Bot)
  // --------------------------------------------------------------------------
  const headGroup = new THREE.Group();
  pixelBotGroup.add(headGroup);

  // 1. Head Outer Armor (Cubic Chamfered Robot Head)
  const headGeo = new THREE.BoxGeometry(1.65, 1.35, 1.35);
  const headMesh = new THREE.Mesh(headGeo, whiteArmorMat);
  headMesh.castShadow = true;
  headMesh.receiveShadow = true;
  headGroup.add(headMesh);

  // 2. Visor Screen (Curved Dark Face with Glowing Cyan Eyes)
  const visorGeo = new THREE.BoxGeometry(1.35, 0.85, 0.15);
  const visor = new THREE.Mesh(visorGeo, visorMat);
  visor.position.set(0, -0.05, 0.73);
  headGroup.add(visor);

  // 3. Tara Guiding Star Antenna & Crown
  const antennaBaseGeo = new THREE.CylinderGeometry(0.12, 0.16, 0.15, 16);
  const antennaBase = new THREE.Mesh(antennaBaseGeo, darkJointMat);
  antennaBase.position.set(0, 0.78, 0);
  headGroup.add(antennaBase);

  const antennaStemGeo = new THREE.CylinderGeometry(0.045, 0.045, 0.35, 12);
  const antennaStem = new THREE.Mesh(antennaStemGeo, amberMat);
  antennaStem.position.set(0, 1.0, 0);
  headGroup.add(antennaStem);

  // 4-Point Golden Star Crest on Top of Tara's Head
  const starCenterGeo = new THREE.BoxGeometry(0.24, 0.24, 0.24);
  const starCenter = new THREE.Mesh(starCenterGeo, amberGlowMat);
  starCenter.position.set(0, 1.25, 0);
  starCenter.rotation.z = Math.PI / 4;
  headGroup.add(starCenter);

  const starHGeo = new THREE.BoxGeometry(0.48, 0.12, 0.12);
  const starH = new THREE.Mesh(starHGeo, amberGlowMat);
  starH.position.set(0, 1.25, 0);
  headGroup.add(starH);

  const starVGeo = new THREE.BoxGeometry(0.12, 0.48, 0.12);
  const starV = new THREE.Mesh(starVGeo, amberGlowMat);
  starV.position.set(0, 1.25, 0);
  headGroup.add(starV);

  // 4. Headphone Ear Discs with Glowing Amber Rings (Left & Right)
  [-0.92, 0.92].forEach((xPos, i) => {
    const earOuterGeo = new THREE.CylinderGeometry(0.38, 0.38, 0.2, 24);
    const earOuter = new THREE.Mesh(earOuterGeo, darkJointMat);
    earOuter.rotation.z = Math.PI / 2;
    earOuter.position.set(xPos, 0, 0);
    earOuter.castShadow = true;
    headGroup.add(earOuter);

    const earGlowGeo = new THREE.TorusGeometry(0.26, 0.04, 16, 32);
    const earGlow = new THREE.Mesh(earGlowGeo, amberGlowMat);
    earGlow.rotation.y = Math.PI / 2;
    earGlow.position.set(xPos + (i === 0 ? -0.11 : 0.11), 0, 0);
    headGroup.add(earGlow);
  });

  // 5. Neck Joint & Torso
  const neckGeo = new THREE.CylinderGeometry(0.35, 0.45, 0.35, 16);
  const neck = new THREE.Mesh(neckGeo, darkJointMat);
  neck.position.set(0, -0.4, 0);
  pixelBotGroup.add(neck);

  const torsoGeo = new THREE.BoxGeometry(1.4, 0.75, 1.0);
  const torso = new THREE.Mesh(torsoGeo, whiteArmorMat);
  torso.position.set(0, -0.85, 0);
  torso.castShadow = true;
  pixelBotGroup.add(torso);

  // Chest Logo (Vistaara 4-Square Geometric Emblem)
  const chestPixelGeo = new THREE.BoxGeometry(0.09, 0.09, 0.04);
  const chestOffsets = [
    [-0.06, 0.06, blueprintMat],
    [0.06, 0.06, amberGlowMat],
    [-0.06, -0.06, cyanGlowMat],
    [0.06, -0.06, darkJointMat]
  ];
  chestOffsets.forEach(cfg => {
    const cp = new THREE.Mesh(chestPixelGeo, cfg[2]);
    cp.position.set(cfg[0], -0.82 + cfg[1], 0.52);
    pixelBotGroup.add(cp);
  });

  // --------------------------------------------------------------------------
  // 6. Floating Orbiting 3D Voxel Cubes (Blueprint, Amber, Cyan)
  // --------------------------------------------------------------------------
  const voxelCubes = [];
  const voxelConfig = [
    { mat: blueprintMat, size: 0.22, r: 1.6, speed: 1.2, offset: 0 },
    { mat: amberGlowMat, size: 0.24, r: 1.8, speed: 1.0, offset: Math.PI * 0.5 },
    { mat: cyanGlowMat, size: 0.18, r: 1.5, speed: 1.4, offset: Math.PI },
    { mat: amberMat, size: 0.16, r: 1.7, speed: 1.1, offset: Math.PI * 1.5 }
  ];

  voxelConfig.forEach(cfg => {
    const vg = new THREE.BoxGeometry(cfg.size, cfg.size, cfg.size);
    const cube = new THREE.Mesh(vg, cfg.mat);
    cube.castShadow = true;
    scene.add(cube);
    voxelCubes.push({ mesh: cube, cfg });
  });

  // --------------------------------------------------------------------------
  // Interaction Controls (Drag to orbit, HUD buttons)
  // --------------------------------------------------------------------------
  let isDragging = false;
  let previousMousePosition = { x: 0, y: 0 };
  let targetRotationY = 0.55;
  let targetRotationX = 0.12;

  container.addEventListener('mousedown', (e) => {
    isDragging = true;
    previousMousePosition = { x: e.clientX, y: e.clientY };
  });

  window.addEventListener('mouseup', () => {
    isDragging = false;
  });

  window.addEventListener('mousemove', (e) => {
    if (!isDragging) return;
    const deltaX = e.clientX - previousMousePosition.x;
    const deltaY = e.clientY - previousMousePosition.y;
    targetRotationY += deltaX * 0.008;
    targetRotationX += deltaY * 0.005;
    targetRotationX = Math.max(-0.25, Math.min(0.65, targetRotationX));
    previousMousePosition = { x: e.clientX, y: e.clientY };
  });

  // Wireframe Mode Button
  const wireframeBtn = document.getElementById('stageWireframeBtn');
  if (wireframeBtn) {
    wireframeBtn.addEventListener('click', () => {
      isWireframe = !isWireframe;
      whiteArmorMat.wireframe = isWireframe;
      darkJointMat.wireframe = isWireframe;
      blueprintMat.wireframe = isWireframe;
      amberMat.wireframe = isWireframe;
      wireframeBtn.textContent = isWireframe ? 'SOLID' : 'WIREFRAME';
      if (soundEnabled) playClickSound();
    });
  }

  // Expression Cycle Button
  const exprCycleList = ['happy', 'excited', 'focused', 'cheering', 'curious'];
  let currentExprIndex = 0;
  const exprCycleBtn = document.getElementById('stageExpressionBtn');

  function setPixelExpression(expr) {
    drawPixelEyes(expr);
    if (exprCycleBtn) {
      exprCycleBtn.textContent = `EXPRESSION: ${expr.toUpperCase()}`;
    }
  }
  setPixelExpressionGlobal = setPixelExpression;

  if (exprCycleBtn) {
    exprCycleBtn.addEventListener('click', () => {
      currentExprIndex = (currentExprIndex + 1) % exprCycleList.length;
      const nextExpr = exprCycleList[currentExprIndex];
      setPixelExpression(nextExpr);
      playChirpSound(nextExpr);
    });
  }

  // Reset Orbit Button
  const resetOrbitBtn = document.getElementById('stageResetBtn');
  if (resetOrbitBtn) {
    resetOrbitBtn.addEventListener('click', () => {
      targetRotationY = 0.55;
      targetRotationX = 0.12;
      if (soundEnabled) playClickSound();
    });
  }

  // Telemetry HUD Elements
  const hudRpm = document.getElementById('hudMotorRpm');
  const hudHeading = document.getElementById('hudChassisHeading');

  // Animation Loop
  const clock = new THREE.Clock();
  function animate() {
    requestAnimationFrame(animate);
    const time = clock.getElapsedTime();

    if (!isDragging) {
      targetRotationY += 0.003;
    }

    pixelBotGroup.rotation.y += (targetRotationY - pixelBotGroup.rotation.y) * 0.08;
    pixelBotGroup.rotation.x += (targetRotationX - pixelBotGroup.rotation.x) * 0.08;

    // Gentle head nodding / floating
    headGroup.position.y = 0.4 + Math.sin(time * 2.2) * 0.04;
    headGroup.rotation.z = Math.sin(time * 1.5) * 0.02;

    // Orbiting 3D Voxel Cubes
    voxelCubes.forEach(({ mesh, cfg }) => {
      const angle = time * cfg.speed + cfg.offset;
      mesh.position.x = Math.cos(angle) * cfg.r;
      mesh.position.z = Math.sin(angle) * cfg.r;
      mesh.position.y = 0.3 + Math.sin(angle * 2) * 0.25;
      mesh.rotation.x += 0.02;
      mesh.rotation.y += 0.03;
    });

    if (hudRpm) {
      hudRpm.textContent = `${Math.floor(2800 + Math.sin(time * 3.5) * 120)} RPM`;
    }
    if (hudHeading) {
      const deg = Math.floor(((pixelBotGroup.rotation.y % (Math.PI * 2)) * 180) / Math.PI);
      hudHeading.textContent = `${(deg < 0 ? deg + 360 : deg)}°`;
    }

    camera.lookAt(0, 0.1, 0);
    renderer.render(scene, camera);
  }
  animate();

  window.addEventListener('resize', () => {
    if (!container) return;
    camera.aspect = container.clientWidth / container.clientHeight;
    camera.updateProjectionMatrix();
    renderer.setSize(container.clientWidth, container.clientHeight);
  });
}

/* ==========================================================================
   5. MASCOT INTERACTION (Mood Switchers & Meet Tara Section)
   ========================================================================== */
function initMascotInteractions() {
  const bubble = document.getElementById('heroMascotBubble');
  const moodPills = document.querySelectorAll('.mood-pill-btn');
  const exprCards = document.querySelectorAll('.expression-card');

  const moodDialogues = {
    happy: '"Hi, I\'m Tara! Your builder star companion. Different minds create a bolder tomorrow. Ready to build?"',
    excited: '"WOOHOO! Stage 02 Build sprint is underway! Connect with mentors and test your API endpoints!"',
    focused: '"Scanning system architecture: clean microservices, reactive state management, and optimized database queries."',
    cheering: '"Let\'s go App Track and Web Track! 50+ teams transforming ideas into working reality!"',
    curious: '"What if we benchmark edge LLM inference against our 100-point rubric? Let\'s run a test in the Evaluator!""'
  };

  function updateMascotMood(mood) {
    if (bubble && moodDialogues[mood]) {
      bubble.textContent = moodDialogues[mood];
      bubble.style.animation = 'none';
      bubble.offsetHeight; // trigger reflow
      bubble.style.animation = 'speechPop 0.3s cubic-bezier(0.16, 1, 0.3, 1)';
    }

    // Sync mood pill buttons
    moodPills.forEach(p => {
      p.classList.toggle('active', p.getAttribute('data-mood') === mood);
    });

    // Sync expression showcase cards
    exprCards.forEach(c => {
      c.classList.toggle('active', c.getAttribute('data-expr') === mood);
    });

    // Sync 3D Three.js stage face
    if (typeof setPixelExpressionGlobal === 'function') {
      setPixelExpressionGlobal(mood);
    }

    playChirpSound(mood);
  }

  moodPills.forEach(pill => {
    pill.addEventListener('click', () => {
      const mood = pill.getAttribute('data-mood');
      updateMascotMood(mood);
    });
  });

  exprCards.forEach(card => {
    card.addEventListener('click', () => {
      const expr = card.getAttribute('data-expr');
      updateMascotMood(expr);
    });
  });
}

/* ==========================================================================
   6. FLOATING INTERACTIVE MASCOT COMPANION (Tara Corner Widget)
   ========================================================================== */
function initFloatingCompanion() {
  const companionBtn = document.getElementById('companionBtn');
  const bubble = document.getElementById('companionBubble');
  if (!companionBtn || !bubble) return;

  const tips = [
    '"Explore Stage 01: Attend 3–5 interactive industry masterclasses to validate your problem space!"',
    '"15+ active mentors from leading tech companies are waiting at the Mentor Hub desks in Stage 03!"',
    '"Real-world impact counts for 30 points on the official rubric. Focus on genuine user utility!"',
    '"Students aged 14–26 retain 100% intellectual property (IP) ownership over all code and assets!"',
    '"Demo Day pitches in Stage 04 are 3 minutes live demo + 2 minutes technical jury Q&A."',
    '"10 target focus themes: AI Central, Cyber Security, Cloud Computing, FinTech, and more!"'
  ];

  let tipIndex = 0;
  let bubbleTimeout = null;

  function showCompanionTip(text) {
    bubble.textContent = text;
    bubble.classList.add('show');
    clearTimeout(bubbleTimeout);
    bubbleTimeout = setTimeout(() => {
      bubble.classList.remove('show');
    }, 6000);
  }

  companionBtn.addEventListener('click', () => {
    tipIndex = (tipIndex + 1) % tips.length;
    showCompanionTip(tips[tipIndex]);
    playChirpSound('excited');
  });

  // Initial welcome greeting after 2.5 seconds
  setTimeout(() => {
    showCompanionTip('"Hi builder! Click me anytime for architectural tips & track guidance!"');
  }, 2500);

  // Trigger contextual hints when scrolling into sections
  const observer = new IntersectionObserver((entries) => {
    entries.forEach(entry => {
      if (entry.isIntersecting) {
        if (entry.target.id === 'evaluator') {
          showCompanionTip('"Balance your Impact (30), Architecture (40), and UX/Demo (30) in the Rubric above!"');
        } else if (entry.target.id === 'ecosystem') {
          showCompanionTip('"Click on any zone in the architecture diagram to inspect Stage 01 through 04 checkpoints!"');
        } else if (entry.target.id === 'prizes') {
          showCompanionTip('"₹3,00,000+ in seed grants, $25K cloud credits, and incubation cohorts await winners!"');
        }
      }
    });
  }, { threshold: 0.4 });

  document.querySelectorAll('#ecosystem, #evaluator, #prizes').forEach(s => observer.observe(s));
}

