  const zoneTag = document.getElementById('zoneTag');
  const zoneTitle = document.getElementById('zoneTitle');
  const zoneScore = document.getElementById('zoneScore');
  const zoneDesc = document.getElementById('zoneDesc');
  const rulesList = document.getElementById('zoneRulesList');
  const tipText = document.getElementById('zoneTipText');
  const tipImg = document.getElementById('zoneTipImg');

  const zoneData = {
    productEngine: {
      tag: 'STAGE 02: PRODUCT ENGINE',
      title: 'App & Web Product Engine (50+ Projects)',
      score: '50+ Teams · 200–300 Builders',
      desc: 'The technical heartbeat of Vistaara. Student teams design and engineer complete, functional mobile apps and web platforms addressing genuine community and market challenges.',
      rules: [
        'Original Codebase: All code written from scratch during the hackathon marathon.',
        'Two Core Tracks: App Development (Flutter/React Native/Swift) or Web Development (Next.js/React).',
        'Target Themes: Mapped to 1 of 10 focus themes (AI Central, FinTech, Cyber Security, etc.).',
        'Production Readiness: Live functional deployment with sandboxed databases and API integrations.'
      ],
      tip: 'Do not build in isolation. Leverage industry seminars and mentor checkpoints to validate user problem clarity before scaling complexity.'
    },
    founderStage: {
      tag: 'STAGE 01: FOUNDER CONVERSATIONS',
      title: 'Keynote Stage & Industry Seminars',
      score: '3–5 Curated Industry Sessions',
      desc: 'Kickoff ceremonies and founder discussions woven directly into the hackathon sprint. Industry leaders deliver masterclasses on scalable architecture, user discovery, and venture pitching.',
      rules: [
        'Interactive Seminars: Live fireside chats with startup CTOs and tech leads.',
        'Starter Kit Briefings: Technical walkthroughs of official starter repos and sandboxes.',
        'Problem Statement Deep Dives: Direct access to partner challenges and prompt tracks.',
        'Attendance & Q&A: Open floor for all 200–300 student participants.'
      ],
      tip: 'Attend keynote seminars for real-world engineering perspectives. Founders frequently highlight common architectural and product pitfalls.'
    },
    mentorHub: {
      tag: 'STAGE 03: MENTOR HUB',
      title: '1-on-1 Mentor Hub & Code Review Desks',
      score: '15+ Mentors · 10+ Tech Companies',
      desc: 'Dedicated technical mentor desks where senior engineers and founders sit down with student teams for deep-dive architecture reviews, UX critique, and debugging sessions.',
      rules: [
        'Desk Checkpoints: Scheduled 1-on-1 review slots for each team throughout the sprint.',
        'API & Schema Audit: Mentors review database models, auth flows, and security.',
        'UX Workflow Defense: Stress-testing user onboarding and mobile/web accessibility.',
        'Industry Exposure: High-trust interactions designed to bridge students with hiring teams.'
      ],
      tip: 'Engage with mentors early during Stage 03 checkpoints. Desk-side code and architecture reviews identify bottlenecks before Demo Day.'
    },
    cloudStack: {
      tag: 'INFRASTRUCTURE: TECH SANDBOX',
      title: 'Cloud, AI & 10 Focus Themes',
      score: 'Pre-Provisioned Sandbox API Credits',
      desc: 'Enterprise developer infrastructure provided to all registered builders, including sandboxed LLM tokens, cloud compute instances, vector databases, and security APIs.',
      rules: [
        '10 Focus Themes: AI Central, Cyber Security, Cloud, FinTech, Blockchain, Healthcare, IoT, Web3, Education, Sustainability.',
        'Sandbox Access: Free developer tokens for Gemini 1.5, AWS/GCP credits, Supabase, and Pinecone.',
        'Open Source Freedom: Full permission to utilize approved open-source libraries and SDKs.',
        'Automated CI/CD: Pre-configured deployment pipelines to Vercel and app distribution channels.'
      ],
      tip: 'Utilize pre-provisioned developer credits for compute, vector stores, and model APIs to achieve production-grade performance.'
    },
    demoArena: {
      tag: 'STAGE 04: FINAL PROJECT DEMO',
      title: 'Stage 04 Final Project Demo & Showcase',
      score: '100-Point Evaluation Rubric',
      desc: 'The grand finale where top teams present live 3-minute working prototype demonstrations followed by 2 minutes of technical defense before an industry jury panel.',
      rules: [
        '3-Minute Pitch: Strict time limit for problem presentation and live working demo.',
        '2-Minute Q&A: Technical scrutiny by jury of founders, CTOs, and investors.',
        '100-Pt Rubric: 30 pts Impact, 40 pts Architecture, 30 pts UX & Demo Delivery.',
        'Seed Grants & Incubation: Winners receive equity-free capital, cloud credits, and accelerator fast-tracks.'
      ],
      tip: 'Lead with a live working prototype demonstration. The industry jury evaluates working codebases, data integrity, and technical defense.'
    }
  };

  hotspots.forEach(btn => {
    btn.addEventListener('click', () => {
      hotspots.forEach(b => b.classList.remove('active'));
      btn.classList.add('active');

      const zoneKey = btn.getAttribute('data-zone');
      const data = zoneData[zoneKey] || zoneData.productEngine;

      if (zoneTag) zoneTag.textContent = data.tag;
      if (zoneTitle) zoneTitle.textContent = data.title;
      if (zoneScore) zoneScore.textContent = data.score;
      if (zoneDesc) zoneDesc.textContent = data.desc;

      if (rulesList) {
        rulesList.innerHTML = data.rules.map(r => `<li>${r}</li>`).join('');
      }

      if (tipText) {
        tipText.textContent = data.tip;
      }

      if (soundEnabled) playClickSound();
    });
  });
}

/* ==========================================================================
   GAME THEME & ARENA BLUEPRINT
   ========================================================================== */

.arena-stage-layout {
  display: grid;
  grid-template-columns: 1.25fr 0.75fr;
  gap: 24px;
  align-items: start;
}

.arena-visualizer-box {
  background: var(--paper-pure);
  border: 1px solid var(--line-light);
  border-radius: var(--radius-sm);
  padding: 18px;
  position: relative;
}

.arena-svg-wrapper {
  width: 100%;
  aspect-ratio: 16/10;
  background: #fcfcf9;
  border: 1px solid var(--line-light);
  border-radius: var(--radius-xs);
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
}

.arena-hotspot-btn {
  cursor: pointer;
  pointer-events: all;
}

/* Soft expanding animation on the inner visual, completely isolating hit bounds */
.arena-hotspot-btn .hotspot-visual {
  transition: transform 0.3s cubic-bezier(0.2, 0.9, 0.3, 1), filter 0.3s ease;
  transform-box: fill-box;
  transform-origin: center center;
  pointer-events: none; /* Prevents child elements from flickering mouse events */
}

/* Hover: subtle, smooth, soft expansion without jitter */
.arena-hotspot-btn:hover .hotspot-visual {
  transform: scale(1.04);
  filter: drop-shadow(0 0 7px rgba(0, 209, 255, 0.65));
}

/* Active selected element state */
.arena-hotspot-btn.active .hotspot-visual {
  transform: scale(1.02);
  filter: drop-shadow(0 0 9px rgba(37, 99, 235, 0.8));
}

.arena-hotspot-btn.active:hover .hotspot-visual {
  transform: scale(1.05);
  filter: drop-shadow(0 0 12px rgba(0, 209, 255, 0.85));
}

.arena-zone-sidebar {
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.zone-detail-panel {
  background: var(--paper-pure);
  border: 1px solid var(--line-strong);
  border-radius: var(--radius-sm);
