}

.zone-rules-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 8px;
  font-size: 0.86rem;
  color: var(--ink-secondary);
}

.zone-rules-list li {
  position: relative;
  padding-left: 14px;
}

.zone-rules-list li::before {
  content: '>';
  position: absolute;
  left: 0;
  color: var(--ink);
  font-family: var(--font-mono);
  font-weight: 700;
