/* ==========================================================================
   11. REGISTRATION MODAL & DIGITAL BUILDER PASS GENERATOR
   ========================================================================== */
function initRegistrationModal() {
  const modal = document.getElementById('registrationModal');
  const openBtns = document.querySelectorAll('.open-register-modal-btn');
  const closeBtn = document.getElementById('modalCloseBtn');
  const nextBtn = document.getElementById('nextStepBtn');
  const prevBtn = document.getElementById('prevStepBtn');
  const submitBtn = document.getElementById('submitRegBtn');
  const stepPills = document.querySelectorAll('.step-pill');
  const steps = [
    document.getElementById('modalStep1'),
    document.getElementById('modalStep2'),
    document.getElementById('modalStep3'),
    document.getElementById('modalStep4')
  ];

  let currentStep = 0;

  function setStep(stepIndex) {
    currentStep = stepIndex;
    steps.forEach((step, idx) => {
      if (step) step.style.display = idx === currentStep ? 'block' : 'none';
    });

    stepPills.forEach((pill, idx) => {
      pill.classList.toggle('active', idx === currentStep);
    });

    if (prevBtn) prevBtn.style.display = currentStep > 0 && currentStep < 3 ? 'inline-flex' : 'none';
    if (nextBtn) nextBtn.style.display = currentStep < 2 ? 'inline-flex' : 'none';
    if (submitBtn) submitBtn.style.display = currentStep === 2 ? 'inline-flex' : 'none';
  }

  function openModal() {
    if (modal) {
      modal.classList.add('active');
      setStep(0);
      if (soundEnabled) playClickSound();
    }
  }

  function closeModal() {
    if (modal) {
      modal.classList.remove('active');
    }
  }

  openBtns.forEach(btn => btn.addEventListener('click', openModal));
  if (closeBtn) closeBtn.addEventListener('click', closeModal);

  if (modal) {
    modal.addEventListener('click', (e) => {
      if (e.target === modal) closeModal();
    });
  }

  if (nextBtn) {
    nextBtn.addEventListener('click', () => {
      if (currentStep < 2) {
        setStep(currentStep + 1);
        if (soundEnabled) playClickSound();
      }
    });
  }

  if (prevBtn) {
    prevBtn.addEventListener('click', () => {
      if (currentStep > 0) {
        setStep(currentStep - 1);
        if (soundEnabled) playClickSound();
      }
    });
  }

  if (submitBtn) {
    submitBtn.addEventListener('click', () => {
      // Transfer values to Digital Pass
      const teamName = document.getElementById('regTeamName')?.value || 'ORBIT BUILDERS';
      const division = document.getElementById('regDivision')?.value || 'App Development Track';
      const alliance = document.getElementById('regAlliance')?.value || 'AI Central';
      const school = document.getElementById('regSchool')?.value || 'IIT DELHI';
      const captain = document.getElementById('regCaptain')?.value || 'ARYAN SHARMA';

      const passTeam = document.getElementById('passCardTeam');
      const passDiv = document.getElementById('passCardDivision');
      const passSchool = document.getElementById('passCardSchool');
      const passCapt = document.getElementById('passCardCaptain');
      const passSerial = document.getElementById('passCardSerial');

      if (passTeam) passTeam.textContent = teamName.toUpperCase();
      if (passDiv) passDiv.textContent = `${division.toUpperCase()} — ${alliance.toUpperCase()}`;
      if (passSchool) passSchool.textContent = school.toUpperCase();
      if (passCapt) passCapt.textContent = captain.toUpperCase();
      if (passSerial) {
        const randId = Math.floor(1000 + Math.random() * 9000);
        passSerial.textContent = `VST-2026-${randId}`;
      }

      setStep(3);
      if (soundEnabled) playSuccessSound();
    });
  }

  const downloadPassBtn = document.getElementById('downloadPassBtn');
  if (downloadPassBtn) {
    downloadPassBtn.addEventListener('click', () => {
      alert('Official Vistaara Digital Builder Pass verified and saved! Present this serial at Stage 01 Check-in.');
      if (soundEnabled) playSuccessSound();
    });
  }
}

