   12. MARQUEE DUPLICATION
   ========================================================================== */
function initMarquee() {
  const track = document.getElementById('partnerMarqueeTrack');
  if (!track) return;
  const clone = track.innerHTML;
  track.innerHTML += clone;
}

/* ==========================================================================
   13. INTERACTIVE PALETTE SWITCHER ENGINE
   ========================================================================== */
function initThemeSwitcher() {
  const triggerBtn = document.getElementById('paletteTriggerBtn');
  const panel = document.getElementById('paletteDropdownPanel');
  const optionBtns = document.querySelectorAll('.palette-option-btn');
  const activeLabel = document.getElementById('activePaletteLabel');
  const activeDot1 = document.getElementById('activeDot1');
  const activeDot2 = document.getElementById('activeDot2');

  const themeMeta = {
    blueprint: { name: 'BLUEPRINT', primary: '#1E3A73', accent: '#FFB703' },
    emerald:   { name: 'EMERALD',   primary: '#065F46', accent: '#10B981' },
    violet:    { name: 'VIOLET',    primary: '#5B21B6', accent: '#8B5CF6' },
    solar:     { name: 'SOLAR',     primary: '#C2410C', accent: '#F97316' },
    monochrome:{ name: 'MONOCHROME',primary: '#171717', accent: '#2563EB' }
  };

  function applyTheme(themeKey) {
    const meta = themeMeta[themeKey] || themeMeta.blueprint;
    document.documentElement.setAttribute('data-theme', themeKey);
    localStorage.setItem('vistaara_theme', themeKey);

    if (activeLabel) activeLabel.textContent = `PALETTE: ${meta.name}`;
    if (activeDot1) activeDot1.style.background = meta.primary;
    if (activeDot2) activeDot2.style.background = meta.accent;

    optionBtns.forEach(btn => {
      btn.classList.toggle('active', btn.getAttribute('data-theme') === themeKey);
    });
  }

  // Load saved theme or default to blueprint
  const savedTheme = localStorage.getItem('vistaara_theme') || 'blueprint';
  applyTheme(savedTheme);

  if (triggerBtn && panel) {
    triggerBtn.addEventListener('click', (e) => {
      e.stopPropagation();
      const isOpen = panel.classList.contains('open');
      panel.classList.toggle('open', !isOpen);
      triggerBtn.setAttribute('aria-expanded', !isOpen);
      if (soundEnabled) playClickSound();
    });

    document.addEventListener('click', (e) => {
      if (!panel.contains(e.target) && e.target !== triggerBtn) {
        panel.classList.remove('open');
        triggerBtn.setAttribute('aria-expanded', 'false');
      }
    });

    document.addEventListener('keydown', (e) => {
      if (e.key === 'Escape') {
        panel.classList.remove('open');
        triggerBtn.setAttribute('aria-expanded', 'false');
      }
    });
  }

  optionBtns.forEach(btn => {
    btn.addEventListener('click', () => {
      const selectedTheme = btn.getAttribute('data-theme');
      if (selectedTheme) {
        applyTheme(selectedTheme);
        if (panel) panel.classList.remove('open');
        if (triggerBtn) triggerBtn.setAttribute('aria-expanded', 'false');
        if (soundEnabled) playSuccessSound();
      }
    });
  });
}

