/* ==========================================================================
   SCHEDULE CONSOLE (BRUTALIST 2-COLUMN TIMELINE)
   ========================================================================== */

.schedule-console-wrapper {
  margin-top: 36px;
  background: var(--paper-pure);
  border: 1.5px solid var(--ink);
  border-radius: var(--radius-sm);
  box-shadow: 4px 4px 0 var(--ink);
  overflow: hidden;
  font-family: var(--font-sans);
}

/* Top HUD Bar */
.schedule-top-hud {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 12px;
  padding: 10px 18px;
  background: var(--ink);
  color: var(--paper-pure);
  font-family: var(--font-mono);
  font-size: 0.72rem;
  letter-spacing: 0.04em;
  border-bottom: 1.5px solid var(--ink);
}

.hud-left {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-wrap: wrap;
}

.hud-rec-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: #ef4444;
  box-shadow: 0 0 8px #ef4444;
  animation: pulseRec 1.6s ease-in-out infinite;
}

@keyframes pulseRec {
  0%, 100% { opacity: 1; transform: scale(1); }
  50% { opacity: 0.35; transform: scale(0.85); }
}

.hud-status-text {
  font-weight: 700;
  color: #ef4444;
  letter-spacing: 0.08em;
}

.hud-divider {
  opacity: 0.3;
}

.hud-meta-item {
  color: rgba(255, 255, 255, 0.75);
}

.hud-meta-item strong {
  color: #ffffff;
}

.hud-right {
  display: flex;
  align-items: center;
  gap: 8px;
}

.hud-chip {
  padding: 3px 8px;
  font-size: 0.68rem;
  font-weight: 700;
  border: 1px solid rgba(255, 255, 255, 0.25);
  border-radius: 2px;
  background: rgba(255, 255, 255, 0.08);
  color: #ffffff;
}

.hud-chip-accent {
  background: var(--blueprint);
  border-color: var(--blueprint);
  color: #ffffff;
}

.hud-star {
  color: var(--amber);
  margin-right: 2px;
}

/* Two Column Grid */
.schedule-two-col-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  background: var(--paper-pure);
}

.schedule-col {
  display: flex;
  flex-direction: column;
}

.schedule-col:first-child {
  border-right: 1.5px solid var(--line);
}

.schedule-col-header {
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 16px 20px;
  background: var(--paper);
  border-bottom: 1.5px solid var(--line);
}

.schedule-day-badge {
  font-family: var(--font-mono);
  font-size: 0.85rem;
  font-weight: 900;
  padding: 6px 12px;
  background: var(--ink);
  color: var(--paper-pure);
  border-radius: 2px;
  letter-spacing: 0.06em;
}

.schedule-col-meta {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.schedule-col-title {
  font-family: var(--font-display);
  font-size: 0.95rem;
  font-weight: 800;
  color: var(--ink);
  letter-spacing: 0.02em;
}

.schedule-col-sub {
  font-family: var(--font-mono);
  font-size: 0.68rem;
  color: var(--ink-muted);
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

.schedule-items-list {
  display: flex;
  flex-direction: column;
}

/* Schedule Row */
.schedule-row {
  display: grid;
  grid-template-columns: 74px 1fr auto;
  align-items: center;
  gap: 16px;
  padding: 14px 20px;
  border-bottom: 1px solid var(--line-light);
  transition: background var(--transition-fast), border-color var(--transition-fast);
}

.schedule-row:last-child {
  border-bottom: none;
}

.schedule-row:hover {
  background: rgba(0, 82, 204, 0.03);
}

.schedule-time {
  font-family: var(--font-mono);
  font-size: 0.85rem;
  font-weight: 800;
  color: var(--ink);
  padding: 4px 8px;
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: 2px;
  text-align: center;
  letter-spacing: 0.04em;
}

.schedule-item-body {
  display: flex;
  flex-direction: column;
  gap: 3px;
  min-width: 0;
}

.schedule-item-title {
  font-family: var(--font-mono);
  font-size: 0.82rem;
  font-weight: 800;
  color: var(--ink);
  letter-spacing: 0.02em;
  line-height: 1.25;
}

.schedule-item-desc {
  font-size: 0.76rem;
  color: var(--ink-secondary);
  line-height: 1.4;
  white-space: normal;
}

/* Status Tags */
.schedule-tag-wrap {
  display: flex;
  justify-content: flex-end;
  align-items: center;
}

.schedule-status-tag {
  font-family: var(--font-mono);
  font-size: 0.65rem;
  font-weight: 800;
  padding: 3px 8px;
  border-radius: 2px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  border: 1px solid;
  white-space: nowrap;
}

.tag-admin {
  background: rgba(139, 92, 246, 0.1);
  color: #6d28d9;
  border-color: rgba(139, 92, 246, 0.4);
}

.tag-system {
  background: rgba(2, 132, 199, 0.1);
  color: #0369a1;
  border-color: rgba(2, 132, 199, 0.4);
}

.tag-start {
  background: rgba(22, 163, 74, 0.1);
  color: #15803d;
  border-color: rgba(22, 163, 74, 0.4);
}

.tag-pause {
  background: rgba(217, 119, 6, 0.1);
  color: #b45309;
  border-color: rgba(217, 119, 6, 0.4);
}

.tag-check {
  background: rgba(5, 150, 105, 0.1);
  color: #047857;
  border-color: rgba(5, 150, 105, 0.4);
}

.tag-end {
  background: rgba(220, 38, 38, 0.1);
  color: #b91c1c;
  border-color: rgba(220, 38, 38, 0.4);
}

/* Bottom HUD Bar */
.schedule-bottom-hud {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 1px;
  background: var(--line);
  border-top: 1.5px solid var(--ink);
}

.hud-stat-cell {
  background: var(--paper);
  padding: 10px 16px;
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.hud-stat-lbl {
  font-family: var(--font-mono);
  font-size: 0.62rem;
  font-weight: 700;
  color: var(--ink-muted);
  letter-spacing: 0.06em;
}

.hud-stat-val {
  font-family: var(--font-mono);
  font-size: 0.78rem;
  font-weight: 800;
  color: var(--ink);
  letter-spacing: 0.02em;
}

.val-green {
  color: #16a34a;
}

/* Responsive Styles for Schedule */
@media (max-width: 920px) {
  .schedule-two-col-grid {
    grid-template-columns: 1fr;
  }
  .schedule-col:first-child {
    border-right: none;
    border-bottom: 1.5px solid var(--line);
  }
  .schedule-bottom-hud {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (max-width: 580px) {
  .schedule-row {
    grid-template-columns: 1fr;
    gap: 8px;
    align-items: flex-start;
  }
  .schedule-time {
    display: inline-block;
    width: fit-content;
  }
  .schedule-tag-wrap {
    justify-content: flex-start;
  }
  .schedule-top-hud {
    flex-direction: column;
    align-items: flex-start;
  }
  .schedule-bottom-hud {
    grid-template-columns: 1fr;
  }
}

