  border-radius: 5px;
  margin-top: 4px;
}

/* Main VIP Builder Badge Card */
.vip-builder-badge {
  background: radial-gradient(circle at 50% 0%, #172033 0%, #0a0e1a 70%, #05070d 100%);
  border: 2px solid var(--blueprint);
  border-radius: 12px;
  padding: 24px 26px;
  position: relative;
  overflow: hidden;
  box-shadow: 0 0 35px rgba(0, 82, 204, 0.25), 0 20px 45px rgba(0, 0, 0, 0.7);
  transform-style: preserve-3d;
  transition: transform 0.15s ease-out, box-shadow 0.25s ease;
  user-select: none;
}

.vip-builder-badge:hover {
  box-shadow: 0 0 45px rgba(0, 209, 255, 0.35), 0 25px 50px rgba(0, 0, 0, 0.8);
}

/* Holographic Shimmer Foil Overlay */
.badge-holo-foil {
  position: absolute;
  inset: 0;
  pointer-events: none;
  background: linear-gradient(125deg, 
    rgba(255,255,255,0) 0%, 
    rgba(255,255,255,0.03) 25%, 
    rgba(0, 209, 255, 0.12) 40%, 
    rgba(255, 183, 3, 0.14) 52%, 
    rgba(139, 92, 246, 0.12) 65%, 
    rgba(255,255,255,0) 80%);
  background-size: 250% 250%;
  animation: holoShine 7s ease-in-out infinite;
  z-index: 3;
  mix-blend-mode: screen;
}

@keyframes holoShine {
  0% { background-position: 0% 0%; }
  50% { background-position: 100% 100%; }
  100% { background-position: 0% 0%; }
}

/* Cyber Circuit Background Grid */
.badge-circuit-grid {
  position: absolute;
  inset: 0;
  pointer-events: none;
  background-image: 
    linear-gradient(rgba(0, 82, 204, 0.08) 1px, transparent 1px),
    linear-gradient(90deg, rgba(0, 82, 204, 0.08) 1px, transparent 1px);
  background-size: 18px 18px;
  z-index: 1;
}

/* Badge Top Header Band */
.badge-top-band {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 12px;
  position: relative;
  z-index: 4;
}

.badge-brand-group {
  display: flex;
  align-items: center;
  gap: 10px;
}

.badge-pixel-logo {
  display: grid;
  grid-template-columns: repeat(2, 8px);
  gap: 2px;
}

.px-cube {
  width: 8px;
