}

.badge-event-title {
  font-family: var(--font-display);
  font-size: 1.15rem;
  font-weight: 900;
  color: #ffffff;
  letter-spacing: 0.04em;
  line-height: 1.1;
}

.badge-event-sub {
  font-family: var(--font-mono);
  font-size: 0.62rem;
  font-weight: 700;
  color: var(--energy-cyan);
  letter-spacing: 0.08em;
}

.badge-tier-chips {
  display: flex;
  align-items: center;
  gap: 8px;
}

.badge-pill-tier {
  font-family: var(--font-mono);
  font-size: 0.65rem;
  font-weight: 900;
  padding: 4px 10px;
  background: rgba(255, 183, 3, 0.15);
  border: 1px solid var(--amber);
  color: var(--amber);
  border-radius: 3px;
  letter-spacing: 0.08em;
  text-shadow: 0 0 8px rgba(255, 183, 3, 0.4);
}

.badge-serial-stencil {
  font-family: var(--font-mono);
  font-size: 0.85rem;
  font-weight: 900;
  color: #ffffff;
  background: rgba(0, 0, 0, 0.4);
  padding: 3px 8px;
  border: 1px solid rgba(255, 255, 255, 0.2);
  border-radius: 3px;
  letter-spacing: 0.08em;
}

/* Micro Divider */
.badge-micro-divider {
  display: flex;
  align-items: center;
  gap: 10px;
  font-family: var(--font-mono);
  font-size: 0.58rem;
  color: #64748b;
  letter-spacing: 0.08em;
  margin: 14px 0 16px;
  position: relative;
  z-index: 4;
}

.badge-divider-line {
  flex: 1;
  height: 1px;
  background: repeating-linear-gradient(90deg, #334155, #334155 4px, transparent 4px, transparent 8px);
}

/* Badge Main Grid */
.badge-main-grid {
  display: grid;
  grid-template-columns: 1fr 150px;
  gap: 20px;
  align-items: center;
  position: relative;
  z-index: 4;
}

.badge-identity-col {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.badge-field-label {
  font-family: var(--font-mono);
  font-size: 0.65rem;
  font-weight: 700;
  color: #94a3b8;
  letter-spacing: 0.06em;
}

.badge-team-hero {
  font-family: var(--font-display);
  font-size: clamp(1.4rem, 3.2vw, 2.1rem);
  font-weight: 900;
  color: #ffffff;
  letter-spacing: 0.03em;
  line-height: 1.05;
  text-shadow: 0 0 16px rgba(0, 209, 255, 0.35);
  word-break: break-word;
}

.badge-tag-pills {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin: 6px 0;
}

.badge-tag-track {
  font-family: var(--font-mono);
  font-size: 0.68rem;
  font-weight: 800;
  padding: 3px 9px;
  background: rgba(0, 209, 255, 0.12);
  border: 1px solid var(--energy-cyan);
  color: var(--energy-cyan);
  border-radius: 3px;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

.badge-tag-theme {
  font-family: var(--font-mono);
  font-size: 0.68rem;
  font-weight: 800;
  padding: 3px 9px;
  background: rgba(255, 183, 3, 0.12);
  border: 1px solid var(--amber);
  color: var(--amber);
  border-radius: 3px;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

.badge-meta-specs {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px 14px;
  margin-top: 6px;
  padding: 10px 12px;
  background: rgba(15, 23, 42, 0.65);
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 4px;
