  gap: 2px;
}

.spec-lbl {
  font-family: var(--font-mono);
  font-size: 0.58rem;
  font-weight: 700;
  color: #64748b;
  letter-spacing: 0.06em;
}

.spec-val {
  font-family: var(--font-mono);
  font-size: 0.72rem;
