.text-amber {
  color: var(--amber) !important;
}

.badge-auth-bar {
  display: flex;
  align-items: center;
  gap: 6px;
  font-family: var(--font-mono);
  font-size: 0.64rem;
  color: #94a3b8;
  margin-top: 4px;
}

.auth-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: #22c55e;
  box-shadow: 0 0 8px #22c55e;
}

.auth-text strong {
  color: #4ade80;
}

.auth-sep {
  opacity: 0.3;
}

.auth-hash {
  color: #64748b;
  font-size: 0.58rem;
}

/* Scannable QR Column */
.badge-scannable-col {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
}

.scannable-qr-wrap {
  width: 130px;
  height: 130px;
  background: #ffffff;
  border-radius: 6px;
  padding: 6px;
