}

.qr-corner-bracket {
  position: absolute;
  width: 12px;
  height: 12px;
  border: 2.5px solid var(--blueprint);
}

.qr-corner-bracket.top-left { top: -4px; left: -4px; border-right: none; border-bottom: none; }
.qr-corner-bracket.top-right { top: -4px; right: -4px; border-left: none; border-bottom: none; }
.qr-corner-bracket.bottom-left { bottom: -4px; left: -4px; border-right: none; border-top: none; }
.qr-corner-bracket.bottom-right { bottom: -4px; right: -4px; border-left: none; border-top: none; }

