}

.badge-barcode-num {
  font-family: var(--font-mono);
  font-size: 0.55rem;
  color: #94a3b8;
  letter-spacing: 0.1em;
}

/* Ticket Stub Row */
.badge-stub-row {
  position: relative;
  margin: 18px -26px 12px;
  height: 16px;
  display: flex;
  align-items: center;
  z-index: 4;
}

.stub-notch {
  width: 16px;
  height: 16px;
  background: var(--paper);
  border-radius: 50%;
  position: absolute;
  border: 2px solid var(--blueprint);
  z-index: 5;
}

.stub-notch-left {
  left: -8px;
}

.stub-notch-right {
  right: -8px;
}

.stub-dash-line {
  width: 100%;
  height: 1px;
  background: repeating-linear-gradient(90deg, rgba(255,255,255,0.25), rgba(255,255,255,0.25) 6px, transparent 6px, transparent 12px);
}

.badge-footer-telemetry {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 6px;
  font-family: var(--font-mono);
  font-size: 0.6rem;
  color: #64748b;
  letter-spacing: 0.06em;
  position: relative;
  z-index: 4;
}

/* Mobile Responsive Adjustments for Pass */
@media (max-width: 680px) {
  .badge-main-grid {
    grid-template-columns: 1fr;
    gap: 16px;
  }
  .badge-meta-specs {
    grid-template-columns: 1fr;
  }
  .badge-scannable-col {
    flex-direction: row;
    justify-content: space-between;
    width: 100%;
    padding-top: 10px;
    border-top: 1px solid rgba(255,255,255,0.1);
  }
  .badge-barcode-wrap {
    width: auto;
  }
}

/* Print Friendly Styles */
@media print {
  body * {
    visibility: hidden;
  }
  .modal-backdrop, .modal-backdrop * {
    visibility: visible;
  }
  .modal-backdrop {
    position: absolute;
    inset: 0;
    background: transparent;
    padding: 0;
  }
  .modal-window {
    box-shadow: none;
    border: none;
    padding: 0;
    max-width: 100%;
  }
  .modal-close-btn,
  .form-step-indicator,
  #modalStep1,
  .modal-window > h3,
  .modal-window > p,
  .hud-badge,
  .modal-step-pane > div:last-child {
    display: none !important;
  }
  .vip-builder-badge {
    box-shadow: none;
    border: 2px solid #000;
  }
}

