  inset: 0;
  background: rgba(0, 0, 0, 0.7);
  backdrop-filter: blur(10px);
  z-index: 10000;
  display: none;
  align-items: center;
  justify-content: center;
  padding: 20px;
  overflow-y: auto;
}

.modal-backdrop.open { display: flex; }

.modal-window {
  background: var(--paper);
  border: 1.5px solid var(--ink);
  border-radius: var(--radius-sm);
  max-width: 760px;
  width: 100%;
  padding: 28px;
  position: relative;
  box-shadow: 0 20px 50px rgba(0, 0, 0, 0.25);
  animation: modalScale 0.2s cubic-bezier(0.16, 1, 0.3, 1);
}

@keyframes modalScale {
  from { transform: scale(0.97); opacity: 0; }
  to { transform: scale(1); opacity: 1; }
}

.modal-close-btn {
  position: absolute;
  top: 16px;
  right: 16px;
  background: var(--paper-pure);
  border: 1px solid var(--line-light);
  color: var(--ink);
  width: 30px;
  height: 30px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  cursor: pointer;
  font-family: var(--font-mono);
}

.modal-close-btn:hover {
  background: var(--ink);
  color: var(--paper);
}

.form-step-indicator {
  display: flex;
  gap: 6px;
  margin-bottom: 18px;
}

.step-pill {
  flex: 1;
  height: 3px;
  background: var(--line-light);
  border-radius: 2px;
}

.step-pill.active { background: var(--ink); }

.form-grid-2 {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 14px;
}

.form-group {
  display: flex;
  flex-direction: column;
  gap: 6px;
  margin-bottom: 12px;
}

.form-label {
  font-family: var(--font-mono);
  font-size: 0.7rem;
  color: var(--ink-muted);
  text-transform: uppercase;
}

.form-input, .form-select {
  padding: 9px 12px;
  background: var(--paper-pure);
  border: 1px solid var(--line-strong);
  border-radius: var(--radius-xs);
  color: var(--ink);
  font-family: var(--font-body);
  font-size: 0.88rem;
  outline: none;
}

.form-input:focus, .form-select:focus {
  border-color: var(--ink);
}

.pass-ticket-card {
  background: var(--paper-pure);
  border: 2px solid var(--ink);
  border-radius: var(--radius-xs);
  padding: 20px;
  position: relative;
  margin-top: 16px;
}

.pass-ticket-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  border-bottom: 1px dashed var(--line-strong);
  padding-bottom: 10px;
  margin-bottom: 12px;
}

.pass-ticket-body {
  display: grid;
  grid-template-columns: 1fr 100px;
  gap: 16px;
  align-items: center;
}

.pass-qr-box {
  width: 90px;
  height: 90px;
  background: var(--paper);
  border: 1px solid var(--line-light);
  padding: 4px;
  border-radius: var(--radius-xs);
  display: grid;
  place-items: center;
}

