/* ==========================================================================
   11. REGISTRATION MODAL & DIGITAL BUILDER PASS GENERATOR
   ========================================================================== */
function initRegistrationModal() {
  const modal = document.getElementById('registrationModal');
  const openBtns = document.querySelectorAll('.open-register-modal-btn');
  const closeBtn = document.getElementById('modalCloseBtn');
  const submitBtn = document.getElementById('submitRegBtn');
  const fillDemoBtn = document.getElementById('fillDemoCodeBtn');
  const editPassBtn = document.getElementById('editPassBtn');
  const copySerialBtn = document.getElementById('copyPassSerialBtn');
  const downloadPassBtn = document.getElementById('downloadPassBtn');

  const step1 = document.getElementById('modalStep1');
  const step2 = document.getElementById('modalStep2');
  const pill1 = document.getElementById('modalPill1');
  const pill2 = document.getElementById('modalPill2');

  function showStep(stepNum) {
    if (stepNum === 1) {
      if (step1) step1.style.display = 'block';
      if (step2) step2.style.display = 'none';
      if (pill1) pill1.classList.add('active');
      if (pill2) pill2.classList.remove('active');
    } else {
      if (step1) step1.style.display = 'none';
      if (step2) step2.style.display = 'block';
      if (pill1) pill1.classList.remove('active');
      if (pill2) pill2.classList.add('active');
    }
  }

  function openModal() {
    if (modal) {
      modal.classList.add('active');
      showStep(1);
      if (soundEnabled) playClickSound();
    }
  }

  function closeModal() {
    if (modal) {
      modal.classList.remove('active');
    }
  }

  openBtns.forEach(btn => btn.addEventListener('click', openModal));
  if (closeBtn) closeBtn.addEventListener('click', closeModal);

  if (modal) {
    modal.addEventListener('click', (e) => {
      if (e.target === modal) closeModal();
    });
  }

  // Autofill Demo Code helper
  if (fillDemoBtn) {
    fillDemoBtn.addEventListener('click', () => {
      const codeInput = document.getElementById('regPassCode');
      if (codeInput) {
        codeInput.value = 'VST-2026-PASS';
        codeInput.focus();
        codeInput.style.borderColor = 'var(--blueprint)';
      }
      if (soundEnabled) playSuccessSound();
    });
  }

  // Core Pass Generation Logic
  function executePassGeneration() {
    const codeInput = document.getElementById('regPassCode');
    const teamInput = document.getElementById('regTeamName');
    const divSelect = document.getElementById('regDivision');
    const allSelect = document.getElementById('regAlliance');
    const captInput = document.getElementById('regCaptain');
    const schoolInput = document.getElementById('regSchool');

    const passCode = codeInput?.value.trim() || 'VST-2026-PASS';
    const teamName = teamInput?.value.trim() || 'ORBIT BUILDERS';
    const division = divSelect?.value || 'App Development Track';
    const alliance = allSelect?.value || 'AI Central';
    const captain = captInput?.value.trim() || 'ARYAN SHARMA';
    const school = schoolInput?.value.trim() || 'INDIAN INSTITUTE OF TECHNOLOGY';

    if (!passCode) {
      alert('Please enter your unique verification code sent via mail 10 days before the event (or click "Use Demo Code").');
      if (codeInput) codeInput.focus();
      return;
    }

    if (!teamName) {
      alert('Please enter your registered team name.');
      if (teamInput) teamInput.focus();
      return;
    }

    // Populate Pass Elements
    const passTeam = document.getElementById('passCardTeam');
    const passDiv = document.getElementById('passCardDivision');
    const passSchool = document.getElementById('passCardSchool');
    const passCapt = document.getElementById('passCardCaptain');
    const passSerial = document.getElementById('passCardSerial');
    const passCodeVal = document.getElementById('passCardCodeVal');

    const formattedSerial = passCode.toUpperCase().startsWith('VST-') ? passCode.toUpperCase() : `VST-${passCode.toUpperCase()}`;

    if (passTeam) passTeam.textContent = teamName.toUpperCase();
    if (passDiv) passDiv.textContent = `${division.toUpperCase()} — ${alliance.toUpperCase()}`;
    if (passSchool) passSchool.textContent = school.toUpperCase();
    if (passCapt) passCapt.textContent = captain.toUpperCase();
    if (passSerial) passSerial.textContent = formattedSerial;
    if (passCodeVal) passCodeVal.textContent = passCode.toUpperCase();

    showStep(2);
    if (soundEnabled) playSuccessSound();
  }

  window.executePassGeneration = executePassGeneration;

  if (submitBtn) {
    submitBtn.addEventListener('click', executePassGeneration);
  }

  if (editPassBtn) {
    editPassBtn.addEventListener('click', () => {
      showStep(1);
      if (soundEnabled) playClickSound();
    });
  }

  // Copy Pass Serial to Clipboard
  if (copySerialBtn) {
    copySerialBtn.addEventListener('click', () => {
      const serial = document.getElementById('passCardSerial')?.textContent.trim() || 'VST-2026-PASS';
      if (navigator.clipboard) {
        navigator.clipboard.writeText(serial).then(() => {
          const originalText = copySerialBtn.textContent;
          copySerialBtn.textContent = 'COPIED TO CLIPBOARD';
          setTimeout(() => { copySerialBtn.textContent = originalText; }, 2200);
        });
      } else {
        alert(`Pass Serial: ${serial}`);
      }
      if (soundEnabled) playSuccessSound();
    });
  }

  // High-Resolution Canvas PNG Pass Export
  if (downloadPassBtn) {
    downloadPassBtn.addEventListener('click', () => {
      const team = document.getElementById('passCardTeam')?.textContent || 'ORBIT BUILDERS';
      const category = document.getElementById('passCardDivision')?.textContent || 'APP DEVELOPMENT TRACK — AI CENTRAL';
      const serial = document.getElementById('passCardSerial')?.textContent || 'VST-2026-PASS';
      const code = document.getElementById('passCardCodeVal')?.textContent || 'VST-2026-PASS';
      const captain = document.getElementById('passCardCaptain')?.textContent || 'ARYAN SHARMA';
      const school = document.getElementById('passCardSchool')?.textContent || 'INDIAN INSTITUTE OF TECHNOLOGY';

      const canvas = generatePassCanvas({ team, category, serial, code, captain, school });

      canvas.toBlob(blob => {
        if (!blob) return;
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        const slug = team.toLowerCase().replace(/[^a-z0-9]+/g, '-');
        a.href = url;
        a.download = `vistaara-builder-pass-${slug}.png`;
        document.body.appendChild(a);
        a.click();
        document.body.removeChild(a);
        URL.revokeObjectURL(url);
      });

      if (soundEnabled) playSuccessSound();
    });
  }
}

/* Helper: Render High-Resolution Official Digital Pass Badge on HTML5 Canvas */
function generatePassCanvas(data) {
  const canvas = document.createElement('canvas');
  canvas.width = 880;
  canvas.height = 460;
  const ctx = canvas.getContext('2d');

  const activeTheme = document.documentElement.getAttribute('data-theme') || 'blueprint';
  const themeColors = {
    blueprint: { bg: '#0a0e1a', border: '#1e3a73', accent: '#ffb703', cyan: '#00d1ff', grid: 'rgba(30, 58, 115, 0.22)' },
    emerald:   { bg: '#06130b', border: '#065f46', accent: '#10b981', cyan: '#34d399', grid: 'rgba(6, 95, 70, 0.25)' },
    violet:    { bg: '#0d071b', border: '#5b21b6', accent: '#8b5cf6', cyan: '#06b6d4', grid: 'rgba(91, 33, 182, 0.25)' },
    solar:     { bg: '#130d0a', border: '#c2410c', accent: '#f97316', cyan: '#0284c7', grid: 'rgba(194, 65, 12, 0.25)' },
    monochrome:{ bg: '#0a0a0a', border: '#333333', accent: '#2563eb', cyan: '#0ea5e9', grid: 'rgba(255, 255, 255, 0.12)' }
  };
  const theme = themeColors[activeTheme] || themeColors.blueprint;

  // Background Dark Theme
  ctx.fillStyle = theme.bg;
  ctx.fillRect(0, 0, 880, 460);

  // Background Grid Blueprint Pattern
  ctx.strokeStyle = theme.grid;
  ctx.lineWidth = 1;
  for (let x = 0; x < 880; x += 22) {
    ctx.beginPath();
    ctx.moveTo(x, 0);
    ctx.lineTo(x, 460);
    ctx.stroke();
  }
  for (let y = 0; y < 460; y += 22) {
    ctx.beginPath();
    ctx.moveTo(0, y);
    ctx.lineTo(880, y);
    ctx.stroke();
  }

  // Border & Header Accent Strip
  ctx.strokeStyle = theme.border;
  ctx.lineWidth = 3;
  ctx.strokeRect(12, 12, 856, 436);

  ctx.fillStyle = theme.accent;
  ctx.fillRect(12, 12, 856, 6);

  // Brand Mark Pixel Blocks
  ctx.fillStyle = theme.border;
  ctx.fillRect(36, 36, 10, 10);
  ctx.fillStyle = theme.accent;
  ctx.fillRect(48, 36, 10, 10);
  ctx.fillStyle = theme.cyan;
  ctx.fillRect(36, 48, 10, 10);
  ctx.fillStyle = '#ffffff';
  ctx.fillRect(48, 48, 10, 10);

  // Title
  ctx.font = 'bold 22px "Plus Jakarta Sans", sans-serif';
  ctx.fillStyle = '#ffffff';
  ctx.fillText('VISTAARA 2026', 68, 46);

  ctx.font = 'bold 11px "Space Mono", monospace';
  ctx.fillStyle = theme.cyan;
  ctx.fillText('OFFICIAL DIGITAL BUILDER PASS', 68, 62);

  // Serial on Right
  ctx.font = 'bold 16px "Space Mono", monospace';
  ctx.fillStyle = theme.accent;
  ctx.textAlign = 'right';
  ctx.fillText(data.serial, 840, 50);
  ctx.textAlign = 'left';

  // Divider Line
  ctx.strokeStyle = theme.border;
  ctx.setLineDash([5, 5]);
  ctx.beginPath();
  ctx.moveTo(36, 84);
  ctx.lineTo(844, 84);
  ctx.stroke();
  ctx.setLineDash([]);

  // Registered Team Section
  ctx.font = '11px "Space Mono", monospace';
  ctx.fillStyle = '#94a3b8';
  ctx.fillText('REGISTERED BUILDER TEAM:', 36, 118);

  ctx.font = '900 32px "Plus Jakarta Sans", sans-serif';
  ctx.fillStyle = '#ffffff';
  ctx.fillText(data.team, 36, 156);

  // Category Badge Box
  ctx.fillStyle = theme.border;
  ctx.fillRect(36, 178, 540, 32);
  ctx.font = 'bold 12px "Space Mono", monospace';
  ctx.fillStyle = theme.accent;
  ctx.fillText(data.category, 48, 199);

  // Metadata
  ctx.font = '13px "Space Mono", monospace';
  ctx.fillStyle = '#cbd5e1';
  ctx.fillText(`TEAM LEAD: ${data.captain}`, 36, 240);
  ctx.fillText(`INSTITUTION: ${data.school}`, 36, 264);

  // Verification Status Strip
  ctx.fillStyle = 'rgba(39, 201, 63, 0.12)';
  ctx.fillRect(36, 292, 540, 36);
  ctx.strokeStyle = '#27c93f';
  ctx.lineWidth = 1;
  ctx.strokeRect(36, 292, 540, 36);
  ctx.font = 'bold 11px "Space Mono", monospace';
  ctx.fillStyle = '#27c93f';
  ctx.fillText(`VERIFIED ACCESS KEY: ${data.code} • 10-DAY MAIL DISPATCH`, 48, 315);

  // QR Code Box on Right
  const qrX = 640;
  const qrY = 110;
  ctx.fillStyle = '#ffffff';
  ctx.fillRect(qrX, qrY, 190, 190);
  ctx.fillStyle = '#12172b';
  // Standard nested visual position tags
  ctx.fillRect(qrX + 15, qrY + 15, 50, 50);
  ctx.fillStyle = '#ffffff';
  ctx.fillRect(qrX + 25, qrY + 25, 30, 30);
  ctx.fillStyle = theme.border;
  ctx.fillRect(qrX + 33, qrY + 33, 14, 14);

  ctx.fillStyle = '#12172b';
  ctx.fillRect(qrX + 125, qrY + 15, 50, 50);
  ctx.fillStyle = '#ffffff';
  ctx.fillRect(qrX + 135, qrY + 25, 30, 30);
  ctx.fillStyle = theme.border;
  ctx.fillRect(qrX + 143, qrY + 33, 14, 14);

  ctx.fillStyle = '#12172b';
  ctx.fillRect(qrX + 15, qrY + 125, 50, 50);
  ctx.fillStyle = '#ffffff';
  ctx.fillRect(qrX + 25, qrY + 135, 30, 30);
  ctx.fillStyle = theme.border;
  ctx.fillRect(qrX + 33, qrY + 143, 14, 14);

  // QR data points
  ctx.fillStyle = theme.border;
  ctx.fillRect(qrX + 80, qrY + 80, 30, 30);
  ctx.fillStyle = theme.cyan;
  ctx.fillRect(qrX + 120, qrY + 80, 25, 20);
  ctx.fillStyle = theme.accent;
  ctx.fillRect(qrX + 80, qrY + 120, 45, 25);
  ctx.fillStyle = '#12172b';
  ctx.fillRect(qrX + 135, qrY + 135, 35, 35);

  ctx.font = 'bold 9px "Space Mono", monospace';
  ctx.fillStyle = theme.cyan;
  ctx.textAlign = 'center';
  ctx.fillText('SCAN FOR STAGE 01 CHECK-IN', qrX + 95, qrY + 210);
  ctx.textAlign = 'left';

  // Bottom Footer Strip
  ctx.fillStyle = '#12172b';
  ctx.fillRect(12, 385, 856, 50);
  ctx.font = '10px "Space Mono", monospace';
  ctx.fillStyle = '#94a3b8';
  ctx.fillText('VISTAARA 2026 • OFFICIAL BUILDER PASS • 28°38\'N 77°13\'E NEW DELHI', 36, 414);
  ctx.textAlign = 'right';
  ctx.fillStyle = theme.accent;
  ctx.fillText('VALID FOR VENUE ADMISSION', 840, 414);
  ctx.textAlign = 'left';

  return canvas;
}

