.pass-date-gate-banner {
  background: rgba(255, 183, 3, 0.07);
  border: 1.5px solid var(--amber);
  border-radius: 8px;
  padding: 14px 16px;
  margin-bottom: 16px;
  display: flex;
  flex-direction: column;
  gap: 8px;
  position: relative;
  transition: all 0.25s ease;
}

.pass-date-gate-banner.preview-active {
  background: rgba(0, 82, 204, 0.08);
  border-color: var(--blueprint);
}

.pass-date-gate-banner.live-active {
  background: rgba(34, 197, 94, 0.08);
  border-color: #22c55e;
}

.gate-status-pill {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 3px 10px;
  border-radius: 999px;
  font-family: var(--font-mono);
  font-size: 0.68rem;
  font-weight: 800;
  letter-spacing: 0.06em;
  width: fit-content;
  text-transform: uppercase;
}

.gate-status-pill.locked {
  background: rgba(255, 183, 3, 0.18);
  color: #b45309;
  border: 1px solid var(--amber);
}

[data-theme="blueprint"] .gate-status-pill.locked,
[data-theme="emerald"] .gate-status-pill.locked,
[data-theme="violet"] .gate-status-pill.locked,
[data-theme="solar"] .gate-status-pill.locked {
  color: #fef08a;
}

.gate-status-pill.preview {
  background: rgba(0, 82, 204, 0.18);
  color: var(--blueprint);
  border: 1px solid var(--blueprint);
}

.gate-status-pill.live {
  background: rgba(34, 197, 94, 0.18);
  color: #16a34a;
  border: 1px solid #16a34a;
}

.gate-status-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: currentColor;
  animation: gatePulse 1.8s infinite;
}

@keyframes gatePulse {
  0%, 100% { opacity: 1; transform: scale(1); }
  50% { opacity: 0.35; transform: scale(0.75); }
}

.gate-title {
  font-family: var(--font-display);
