  color: var(--ink-secondary);
  line-height: 1.5;
  margin: 0;
}

.gate-countdown-bar {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px 12px;
  background: rgba(18, 23, 43, 0.65);
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: 6px;
  width: fit-content;
  margin-top: 2px;
}

.count-unit {
  display: flex;
  flex-direction: column;
  align-items: center;
  min-width: 38px;
}

.count-val {
  font-family: var(--font-mono);
  font-size: 1.05rem;
  font-weight: 800;
  color: var(--amber);
  line-height: 1.1;
}

.count-lbl {
  font-family: var(--font-mono);
  font-size: 0.58rem;
  color: #94a3b8;
  letter-spacing: 0.05em;
}

.count-colon {
  font-family: var(--font-mono);
  font-weight: 800;
  color: rgba(255, 255, 255, 0.4);
  margin-top: -6px;
}

.gate-toggle-preview-btn {
  background: rgba(255, 255, 255, 0.08);
  border: 1px solid rgba(255, 255, 255, 0.2);
  color: var(--ink);
  font-family: var(--font-mono);
  font-size: 0.72rem;
  font-weight: 700;
  padding: 5px 10px;
  border-radius: 4px;
  cursor: pointer;
  transition: all 0.2s ease;
}

.gate-toggle-preview-btn:hover {
  background: var(--blueprint);
  color: #ffffff;
  border-color: var(--blueprint);
}

.terminal-body .pass-date-gate-banner {
  background: rgba(255, 183, 3, 0.06);
  border-color: rgba(255, 183, 3, 0.4);
  padding: 10px 12px;
}

.terminal-body .gate-title {
  color: #ffffff;
  font-size: 0.84rem;
}

.terminal-body .gate-desc {
  color: #94a3b8;
  font-size: 0.74rem;
}

.terminal-body .gate-toggle-preview-btn {
  color: #ffffff;
  border-color: rgba(255, 255, 255, 0.25);
  background: rgba(255, 255, 255, 0.06);
}

.form-input.date-locked, .form-select.date-locked, .term-input.date-locked {
  opacity: 0.75;
  background: rgba(0, 0, 0, 0.05);
  cursor: not-allowed;
}

.btn-locked-state .btn-offset-content {
  background: #334155 !important;
  color: #94a3b8 !important;
  cursor: not-allowed;
}

@keyframes shakeGateNotice {
  0%, 100% { transform: translateX(0); }
  20%, 60% { transform: translateX(-6px); }
  40%, 80% { transform: translateX(6px); }
}

.gate-attention {
  animation: shakeGateNotice 0.5s ease-in-out;
  border-color: #ef4444 !important;
  box-shadow: 0 0 15px rgba(239, 68, 68, 0.35);
}

