.hero-sticker-cluster {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 10px;
  margin-bottom: 12px;
}

.punk-sticker {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 4px 11px;
  font-family: var(--font-mono);
  font-size: 0.72rem;
  font-weight: 900;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  border: 2px solid #0D0614;
  border-radius: 2px;
  cursor: default;
  transition: transform 0.2s cubic-bezier(0.34, 1.56, 0.64, 1), box-shadow 0.2s ease;
  user-select: none;
}

.punk-sticker:hover {
  transform: scale(1.08) rotate(0deg) !important;
  box-shadow: 0 0 14px var(--amber);
}

.sticker-pink {
  background: var(--amber);
  color: #0D0614;
  box-shadow: 3px 3px 0px #0D0614, 5px 5px 0px var(--blueprint);
}

.sticker-lavender {
  background: var(--blueprint);
  color: #FFFFFF;
  box-shadow: 3px 3px 0px #0D0614, 5px 5px 0px var(--amber);
}

.sticker-white {
  background: #FFFFFF;
  color: #0D0614;
  box-shadow: 3px 3px 0px #0D0614, 5px 5px 0px #7970C1;
}

.sticker-tilt-left { transform: rotate(-3.5deg); }
.sticker-tilt-right { transform: rotate(2.8deg); }
.sticker-tilt-left2 { transform: rotate(-1.8deg); }
.sticker-tilt-right2 { transform: rotate(4.2deg); }

.punk-stamp-kanji {
  font-family: var(--font-mono);
  font-size: 0.68rem;
  font-weight: 900;
  color: var(--amber);
  background: rgba(247, 94, 151, 0.12);
  border: 1.5px dashed var(--amber);
  padding: 2px 8px;
  border-radius: 2px;
  letter-spacing: 0.15em;
  transform: rotate(-2deg);
  display: inline-block;
}

/* Diagonal Hazard Caution Ribbon */
.punk-hazard-ribbon {
  width: 100%;
  overflow: hidden;
  background: repeating-linear-gradient(
    -45deg,
    #F75E97,
    #F75E97 16px,
    #0D0614 16px,
    #0D0614 32px
  );
  padding: 8px 0;
  border-top: 2.5px solid #0D0614;
  border-bottom: 2.5px solid #0D0614;
  box-shadow: 0 0 25px rgba(247, 94, 151, 0.45);
  position: relative;
  z-index: 10;
  margin: 36px 0;
  transform: rotate(-0.8deg);
}

.punk-hazard-inner {
  display: flex;
  gap: 40px;
  width: max-content;
  animation: hazardScroll 24s linear infinite;
  font-family: var(--font-mono);
  font-size: 0.78rem;
  font-weight: 900;
  letter-spacing: 0.12em;
  color: #FFFFFF;
  text-transform: uppercase;
  text-shadow: 1px 1px 0 #000, -1px -1px 0 #000, 1px -1px 0 #000, -1px 1px 0 #000, 0 0 10px #000;
}

@keyframes hazardScroll {
  0% { transform: translateX(0); }
  100% { transform: translateX(-50%); }
}

/* Edgy Terminal Deck Punk Modifications */
.hero-terminal-card {
  position: relative;
  background: #11071B;
  border: 2.5px solid var(--blueprint);
  border-radius: 6px;
  box-shadow: 8px 8px 0px var(--amber), 16px 16px 0px rgba(121, 112, 193, 0.5), 0 20px 40px rgba(0,0,0,0.8);
  transform: rotate(0.8deg);
  transition: transform 0.3s ease, box-shadow 0.3s ease;
}

.hero-terminal-card:hover {
  transform: rotate(0deg) scale(1.01);
  box-shadow: 10px 10px 0px var(--amber), 20px 20px 0px var(--blueprint), 0 25px 50px rgba(0,0,0,0.9);
}

.terminal-tape-corner {
  position: absolute;
  top: -12px;
  right: 28px;
  background: var(--amber);
  color: #0D0614;
  font-family: var(--font-mono);
  font-size: 0.65rem;
  font-weight: 900;
  padding: 3px 12px;
  border: 1.5px solid #0D0614;
  letter-spacing: 0.08em;
  transform: rotate(3deg);
  box-shadow: 2px 2px 0px #0D0614;
  z-index: 20;
}

/* Staggered Title Styling */
.hero-title-main {
  position: relative;
}

.title-line-solid {
  display: inline-block;
  transform: skewX(-3deg) rotate(-1deg);
  text-shadow: 4px 4px 0px rgba(121, 112, 193, 0.4), 0 0 25px rgba(255, 255, 255, 0.2);
}

.title-line-outline {
  display: inline-block;
  transform: skewX(2deg) rotate(1.2deg) translateX(12px);
  -webkit-text-stroke: 2.5px var(--blueprint);
}

.title-line-highlight {
  display: inline-flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 12px;
  transform: rotate(-0.5deg);
  text-shadow: 0 0 30px rgba(247, 94, 151, 0.65);
}

/* Staggered Schematic Items */
.hero-schematic-strip {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(110px, 1fr));
  gap: 12px;
  margin-top: 14px;
}

.hero-schematic-item {
  background: var(--paper-pure);
  border: 1.5px solid var(--blueprint);
  border-radius: 4px;
  padding: 10px 14px;
  box-shadow: 4px 4px 0px #0D0614;
  transition: transform 0.2s ease, border-color 0.2s ease;
}

.hero-schematic-item:nth-child(even) {
  transform: rotate(1deg);
}

.hero-schematic-item:nth-child(odd) {
  transform: rotate(-1deg);
}

.hero-schematic-item:hover {
  transform: translateY(-4px) rotate(0deg) !important;
  border-color: var(--amber);
  box-shadow: 5px 5px 0px var(--amber);
}

/* Edgy Division Showcase Card */
.division-showcase-card {
  background: #150A22;
  border: 2.5px solid var(--blueprint);
  border-radius: 6px;
  box-shadow: 8px 8px 0px var(--amber), 0 15px 35px rgba(0,0,0,0.7);
  transform: rotate(-0.6deg);
  transition: transform 0.25s ease, box-shadow 0.25s ease;
}

.division-showcase-card:hover {
  transform: rotate(0deg);
  box-shadow: 10px 10px 0px var(--amber);
}

.division-tab-btn {
  border: 2px solid var(--blueprint);
  border-radius: 2px;
  font-family: var(--font-mono);
  font-weight: 900;
  transition: transform 0.15s ease, background 0.15s ease;
}

.division-tab-btn:hover {
  transform: translateY(-2px);
  border-color: var(--amber);
  color: var(--amber);
}

.division-tab-btn.active {
  background: var(--amber);
  color: #0D0614;
  border-color: #0D0614;
  box-shadow: 3px 3px 0px var(--blueprint);
  transform: rotate(-1.5deg);
}

/* Schedule Console Punk Enhancements */
.schedule-console-wrapper {
  background: #11071B;
  border: 2.5px solid var(--blueprint);
  box-shadow: 8px 8px 0px var(--blueprint), 16px 16px 0px #0D0614;
  transform: rotate(0.6deg);
}

.schedule-row {
  transition: transform 0.15s ease, background 0.15s ease;
}

.schedule-row:hover {
  background: rgba(247, 94, 151, 0.08);
  transform: translateX(4px);
}

.palette-option-dot {
  width: 11px;
  height: 11px;
  border-radius: 50%;
  border: 1px solid rgba(0, 0, 0, 0.18);
}

