  transform: translateX(4px);
}

/* ==========================================================================
   EDITORIAL BRUTALIST ARCHITECTURE (Reference: XULTRA 100 Inspo)
   ========================================================================== */

/* Topographic Contour Background */
.grid-bg-overlay {
  position: fixed;
  top: 0;
  left: 0;
  width: 100vw;
  height: 100vh;
  pointer-events: none;
  z-index: 0;
  background-image: url('assets/topography.svg');
  background-repeat: repeat;
  background-size: 1100px 750px;
  opacity: 0.38;
}

/* Minimal Editorial Header */
.editorial-header {
  position: sticky;
  top: 0;
  left: 0;
  width: 100%;
  z-index: 120;
  background: var(--header-bg);
  backdrop-filter: blur(14px);
  -webkit-backdrop-filter: blur(14px);
  border-bottom: 1px solid rgba(217, 255, 0, 0.2);
  padding: 10px clamp(16px, 3.5vw, 48px);
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.editorial-header-left {
  display: flex;
  align-items: center;
  gap: clamp(16px, 2.5vw, 36px);
}

.editorial-brand {
  display: inline-flex;
  align-items: center;
  gap: 12px;
  text-decoration: none;
  color: var(--ink);
}

.editorial-brand-logo {
  height: 36px;
  width: auto;
  object-fit: contain;
  filter: drop-shadow(0 0 10px rgba(217, 255, 0, 0.4));
}

.editorial-brand-text {
  font-family: 'Anton', 'Bebas Neue', sans-serif;
  font-size: 1.6rem;
  letter-spacing: 0.04em;
  color: #FFFFFF;
}

.editorial-nav-strip {
  display: flex;
  align-items: center;
  gap: clamp(12px, 1.8vw, 24px);
}

.editorial-nav-link {
  font-family: var(--font-mono);
  font-size: 0.74rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--ink-secondary);
  text-decoration: none;
  font-weight: 700;
  transition: color 0.15s ease;
}

.editorial-nav-link:hover, .editorial-nav-link.active {
  color: var(--neon);
}

.editorial-header-right {
  display: flex;
  align-items: center;
  gap: 16px;
}

.editorial-badge-pill {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border: 1.5px solid var(--neon);
  color: var(--neon);
  font-family: var(--font-mono);
  font-size: 0.68rem;
  font-weight: 800;
  padding: 3px 10px;
  letter-spacing: 0.08em;
  background: rgba(217, 255, 0, 0.05);
}

/* Iconic Square Neon Action Button (↗) */
.square-arrow-btn {
  width: 44px;
  height: 44px;
  background: var(--neon);
  color: #0A0C0E;
  border: 2px solid var(--neon);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  text-decoration: none;
  font-family: var(--font-mono);
  font-size: 1.45rem;
  font-weight: 900;
  line-height: 1;
  position: relative;
  overflow: hidden;
  transition: transform 0.18s cubic-bezier(0.16, 1, 0.3, 1), background 0.18s ease, box-shadow 0.18s ease, color 0.18s ease;
  box-shadow: 0 0 20px rgba(217, 255, 0, 0.35);
}

.square-arrow-btn:hover {
  transform: translate(-3px, -3px) scale(1.04);
  background: #FFFFFF;
  color: #0A0C0E;
  border-color: #FFFFFF;
  box-shadow: 4px 4px 0px var(--neon), 0 0 25px rgba(217, 255, 0, 0.6);
}

/* ==========================================================================
   THE EDITORIAL HERO: SPLIT-SCREEN INVERTED MONUMENT
   ========================================================================== */
.editorial-hero {
  position: relative;
  width: 100%;
  min-height: calc(100vh - 66px);
  display: flex;
  flex-direction: column;
  background: #0A0C0E;
  border-bottom: 2px solid #000;
  overflow: hidden;
  z-index: 1;
}

/* Upper Zone: Dark Grayscale Photography */
.hero-upper-zone {
  position: relative;
  flex: 1 1 56%;
  min-height: clamp(340px, 48vh, 500px);
  display: grid;
  grid-template-columns: 1.15fr 0.85fr;
  background-image: linear-gradient(to right, rgba(10, 12, 14, 0.94) 0%, rgba(10, 12, 14, 0.75) 45%, rgba(10, 12, 14, 0.55) 100%), url('assets/hero-bg.jpg');
  background-size: cover;
  background-position: center right;
  border-bottom: 3px solid #0A0C0E;
  padding: clamp(20px, 3vw, 40px) clamp(20px, 4vw, 56px) 0;
  overflow: hidden;
}

/* Left Column of Upper Zone */
.hero-upper-left {
  position: relative;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  padding-bottom: 10px;
  z-index: 5;
}

/* Mini Vertical Index Nav (matches reference left vertical column) */
.hero-vertical-nav {
  position: absolute;
  top: 10px;
  left: 0;
  display: flex;
  flex-direction: column;
  gap: 8px;
  z-index: 10;
}

.hero-nav-item {
  font-family: var(--font-mono);
  font-size: 0.68rem;
  font-weight: 800;
  letter-spacing: 0.1em;
  color: rgba(255, 255, 255, 0.55);
  text-decoration: none;
  background: none;
  border: none;
  padding: 0;
  text-align: left;
  cursor: pointer;
  transition: color 0.15s ease, transform 0.15s ease;
}

.hero-nav-item:hover {
  color: var(--neon);
  transform: translateX(4px);
}

.hero-lead-block {
  padding-left: clamp(100px, 11vw, 160px);
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.hero-editorial-lead {
  font-family: var(--font-mono);
  font-size: clamp(0.72rem, 1vw, 0.86rem);
  line-height: 1.45;
  max-width: 440px;
  color: var(--neon);
  text-transform: uppercase;
  letter-spacing: 0.04em;
  margin: 0;
  font-weight: 700;
}

.hero-tagline-mono {
  font-family: var(--font-mono);
  font-size: 0.7rem;
  letter-spacing: 0.12em;
  color: #8E939E;
  font-weight: 700;
}

.hero-monumental-title {
  font-family: 'Anton', 'Bebas Neue', sans-serif;
  font-size: clamp(68px, 11.5vw, 158px);
  line-height: 0.82;
  letter-spacing: -0.02em;
  color: var(--neon);
  margin: 0;
  text-transform: uppercase;
  font-weight: 900;
  text-shadow: 0 0 35px rgba(217, 255, 0, 0.35);
}

/* Upper Right Column: Upper Half of 100 */
.hero-upper-right {
  position: relative;
  display: flex;
  align-items: flex-end;
  justify-content: flex-end;
  overflow: hidden;
  z-index: 4;
}

.monumental-number {
  font-family: 'Anton', 'Bebas Neue', 'Impact', sans-serif;
  font-size: clamp(180px, 27vw, 430px);
  line-height: 0.72;
  letter-spacing: -0.04em;
  font-weight: 900;
  user-select: none;
  white-space: nowrap;
}

.num-upper {
  color: var(--neon);
  margin-bottom: -0.06em;
  text-shadow: 0 0 35px rgba(217, 255, 0, 0.4);
}

/* ==========================================================================
   Lower Zone: Split Manifesto Block & Inverted Monumental Digits
   ========================================================================== */
.hero-lower-zone {
  position: relative;
  flex: 0 0 auto;
  display: grid;
  grid-template-columns: 1.15fr 0.85fr;
  min-height: clamp(260px, 34vh, 360px);
  z-index: 5;
}

/* Left Lower: Solid High-Volt Acid Neon Block */
.hero-lower-left-neon {
  background: var(--neon);
  color: #0A0C0E;
  padding: clamp(24px, 3vw, 36px) clamp(20px, 4vw, 56px);
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  gap: 18px;
}

.neon-manifesto-text {
  font-family: var(--font-mono);
  font-size: clamp(0.72rem, 0.92vw, 0.84rem);
  line-height: 1.55;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.02em;
  color: #0A0C0E;
  max-width: 620px;
  margin: 0;
}

.neon-manifesto-text strong {
  font-weight: 900;
  background: #0A0C0E;
  color: var(--neon);
  padding: 1px 5px;
}

.neon-countdown-module {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.neon-countdown-label {
  font-family: var(--font-mono);
  font-size: 0.7rem;
  font-weight: 900;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: #0A0C0E;
  border-left: 3.5px solid #0A0C0E;
  padding-left: 8px;
}

.neon-countdown-digits {
  font-family: 'Anton', 'Bebas Neue', var(--font-mono), sans-serif;
  font-size: clamp(2.6rem, 4.2vw, 4rem);
  line-height: 1;
  font-weight: 900;
  letter-spacing: 0.05em;
  color: #0A0C0E;
  display: flex;
  align-items: baseline;
  gap: 6px;
}

.neon-cta-row {
  display: flex;
  align-items: center;
  gap: 16px;
  flex-wrap: wrap;
}

.neon-claim-btn {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  background: #0A0C0E;
  color: var(--neon);
  font-family: var(--font-mono);
  font-size: 0.82rem;
  font-weight: 900;
  letter-spacing: 0.06em;
  padding: 12px 22px;
  border: 2px solid #0A0C0E;
  cursor: pointer;
  text-decoration: none;
  transition: background 0.15s ease, color 0.15s ease, transform 0.15s ease;
}

.neon-claim-btn:hover {
  background: #FFFFFF;
  color: #0A0C0E;
  border-color: #FFFFFF;
  transform: translateY(-2px);
}

.neon-explore-link {
  font-family: var(--font-mono);
  font-size: 0.78rem;
  font-weight: 900;
  color: #0A0C0E;
  text-decoration: none;
  letter-spacing: 0.06em;
  border-bottom: 2px solid #0A0C0E;
  padding-bottom: 2px;
  transition: opacity 0.15s ease;
}

.neon-explore-link:hover {
  opacity: 0.7;
}

/* Right Lower: Two-Tone Checkerboard Inverted Monumental Number */
.hero-lower-right-split {
  position: relative;
  display: flex;
  height: 100%;
  overflow: hidden;
}

.split-half-neon {
  position: relative;
  width: 44%;
  height: 100%;
  background: var(--neon);
  overflow: hidden;
}

.split-half-dark {
  position: relative;
  flex: 1;
  height: 100%;
  background: #0A0C0E;
  overflow: hidden;
}

.num-lower-black {
  position: absolute;
  top: -0.73em;
  right: calc(100% - 44% - 0.14em);
  color: #0A0C0E;
}

.num-lower-neon {
  position: absolute;
  top: -0.73em;
  right: 0;
  color: var(--neon);
  text-shadow: 0 0 35px rgba(217, 255, 0, 0.4);
}

/* ==========================================================================
   TRIPTYCH HORIZONTAL PANORAMIC STRIP (BUILD • SOLVE • CONNECT)
   ========================================================================== */
.triptych-banner {
  position: relative;
  width: 100%;
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  height: clamp(190px, 25vw, 320px);
  border-top: 2px solid #000;
  border-bottom: 2px solid #000;
  overflow: hidden;
  z-index: 2;
}

.triptych-col {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  border-right: 2px solid #000;
  cursor: pointer;
}

.triptych-col:last-child {
  border-right: none;
}

.triptych-bg-img {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  filter: grayscale(100%) contrast(125%) brightness(0.65);
  transition: transform 0.5s cubic-bezier(0.16, 1, 0.3, 1), filter 0.5s ease;
}

.triptych-overlay {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background: rgba(10, 12, 14, 0.5);
  transition: background 0.3s ease;
}

.triptych-word {
  position: relative;
  z-index: 3;
  font-family: 'Anton', 'Bebas Neue', sans-serif;
  font-size: clamp(48px, 7.5vw, 105px);
  color: var(--neon);
  letter-spacing: 0.08em;
  font-weight: 900;
  line-height: 1;
  text-shadow: 0 0 25px rgba(0, 0, 0, 0.9);
  transition: transform 0.3s cubic-bezier(0.16, 1, 0.3, 1), color 0.3s ease;
}

.triptych-col:hover .triptych-bg-img {
  transform: scale(1.08);
  filter: grayscale(60%) contrast(135%) brightness(0.85);
}

.triptych-col:hover .triptych-overlay {
  background: rgba(10, 12, 14, 0.25);
}

.triptych-col:hover .triptych-word {
  transform: scale(1.06);
  color: #FFFFFF;
  text-shadow: 0 0 30px rgba(217, 255, 0, 0.6);
}

/* ==========================================================================
   EDITORIAL SECTION HEADERS & CHALLENGE PANELS
   ========================================================================== */
.editorial-section-header {
  display: grid;
  grid-template-columns: 1.15fr 0.85fr;
  gap: 32px;
  align-items: flex-end;
  padding: clamp(52px, 6vw, 90px) clamp(20px, 4vw, 56px) 32px;
  border-bottom: 2px solid rgba(217, 255, 0, 0.2);
}

.editorial-mega-title {
  font-family: 'Anton', 'Bebas Neue', sans-serif;
  font-size: clamp(40px, 6.2vw, 80px);
  line-height: 0.9;
  letter-spacing: -0.01em;
  color: var(--neon);
  text-transform: uppercase;
  margin: 0;
}

.editorial-header-right {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.editorial-header-desc {
  font-family: var(--font-mono);
  font-size: clamp(0.75rem, 1vw, 0.88rem);
  line-height: 1.55;
  color: var(--ink-secondary);
  text-transform: uppercase;
  letter-spacing: 0.04em;
  margin: 0;
}

.editorial-header-meta {
  font-family: var(--font-mono);
  font-size: 0.7rem;
  font-weight: 800;
  letter-spacing: 0.1em;
  color: var(--neon);
}

/* ==========================================================================
   FROM PROTOTYPE TO PRODUCTION DEPLOY SHOWCASE
   ========================================================================== */
.showcase-editorial-section {
  position: relative;
  padding: clamp(64px, 8vw, 110px) clamp(20px, 4vw, 56px);
  background: #0A0C0E;
  border-top: 2px solid #000;
  border-bottom: 2px solid #000;
}

.showcase-editorial-title {
  font-family: 'Anton', 'Bebas Neue', sans-serif;
  font-size: clamp(48px, 7.8vw, 110px);
  line-height: 0.88;
  letter-spacing: -0.01em;
  color: var(--neon);
  text-transform: uppercase;
  margin-bottom: 40px;
}

.showcase-grid-cards {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 22px;
}

.showcase-card-panel {
  background: #111418;
  border: 1.5px solid rgba(217, 255, 0, 0.2);
  padding: 28px;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  gap: 16px;
  transition: transform 0.2s ease, border-color 0.2s ease, box-shadow 0.2s ease;
}

.showcase-card-panel:hover {
  transform: translateY(-4px);
  border-color: var(--neon);
  box-shadow: 6px 6px 0px var(--neon);
}

.showcase-card-num {
  font-family: var(--font-mono);
  font-size: 0.75rem;
  font-weight: 900;
  color: var(--neon);
  letter-spacing: 0.1em;
}

.showcase-card-head {
  font-family: 'Anton', 'Bebas Neue', sans-serif;
  font-size: 1.85rem;
  letter-spacing: 0.02em;
  color: #FFFFFF;
  margin: 0;
}

.showcase-card-body {
  font-family: var(--font-mono);
  font-size: 0.78rem;
  line-height: 1.55;
  color: var(--ink-secondary);
  margin: 0;
}

/* ==========================================================================
   BRUTALIST FOOTER WITH GIANT LETTERMARK "V" BLOCK
   ========================================================================== */
.editorial-footer {
  position: relative;
  background: #0A0C0E;
  border-top: 2px solid #000;
  padding: clamp(60px, 8vw, 100px) clamp(20px, 4vw, 56px) clamp(32px, 4vw, 48px);
  background-image: url('assets/topography.svg');
  background-repeat: repeat;
  background-size: 1000px 700px;
  overflow: hidden;
}

.footer-editorial-grid {
  display: grid;
  grid-template-columns: 1.5fr 1fr 1fr;
  gap: clamp(30px, 5vw, 60px);
  margin-bottom: 60px;
}

.footer-badge-box {
  display: inline-block;
  border: 1.5px solid var(--neon);
  color: var(--neon);
  font-family: var(--font-mono);
  font-size: 0.8rem;
  font-weight: 900;
  padding: 4px 10px;
  letter-spacing: 0.08em;
  margin-bottom: 16px;
  background: rgba(217, 255, 0, 0.08);
}

.footer-brand-title {
  font-family: 'Anton', 'Bebas Neue', sans-serif;
  font-size: 2.6rem;
  color: #FFFFFF;
  letter-spacing: 0.04em;
  margin: 0;
}

.footer-brand-tagline {
  font-family: var(--font-mono);
  font-size: 0.75rem;
  letter-spacing: 0.12em;
  color: var(--neon);
  margin-top: 6px;
}

.footer-col-head {
  font-family: var(--font-mono);
  font-size: 0.72rem;
  font-weight: 900;
  letter-spacing: 0.12em;
  color: #FFFFFF;
  margin-bottom: 16px;
}

.footer-col-links {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.footer-col-links a {
  font-family: var(--font-mono);
  font-size: 0.74rem;
  color: var(--ink-secondary);
  text-decoration: none;
  letter-spacing: 0.06em;
  transition: color 0.15s ease, transform 0.15s ease;
  width: fit-content;
}

.footer-col-links a:hover {
  color: var(--neon);
  transform: translateX(4px);
}

.footer-bottom-row {
  display: flex;
  justify-content: space-between;
  align-items: flex-end;
  border-top: 1px solid rgba(217, 255, 0, 0.2);
  padding-top: 24px;
}

.footer-legal-copy {
  display: flex;
  gap: 24px;
  align-items: center;
  font-family: var(--font-mono);
  font-size: 0.7rem;
  color: var(--ink-muted);
  letter-spacing: 0.06em;
  flex-wrap: wrap;
}

.footer-legal-copy a {
  color: var(--ink-muted);
  text-decoration: none;
  transition: color 0.15s ease;
}

.footer-legal-copy a:hover {
  color: var(--neon);
}

/* Monumental Square Neon Lettermark "V" Block */
.footer-giant-lettermark {
  width: clamp(80px, 12vw, 140px);
  height: clamp(80px, 12vw, 140px);
  background: var(--neon);
  display: flex;
  align-items: center;
  justify-content: center;
  color: #0A0C0E;
  font-family: 'Anton', 'Bebas Neue', sans-serif;
  font-size: clamp(64px, 10vw, 120px);
  font-weight: 900;
  line-height: 1;
  box-shadow: 0 0 25px rgba(217, 255, 0, 0.4);
  user-select: none;
  transition: transform 0.2s cubic-bezier(0.16, 1, 0.3, 1), background 0.2s ease;
}

.footer-giant-lettermark:hover {
  transform: scale(1.05) rotate(-2deg);
  background: #FFFFFF;
}

/* ==========================================================================
   RESPONSIVE BREAKPOINTS FOR EDITORIAL BRUTALIST
   ========================================================================== */
@media (max-width: 992px) {
  .hero-upper-zone {
    grid-template-columns: 1fr;
    min-height: auto;
    padding-bottom: 24px;
  }
  .hero-vertical-nav {
    position: static;
    flex-direction: row;
    flex-wrap: wrap;
    gap: 12px;
    margin-bottom: 20px;
  }
  .hero-lead-block {
    padding-left: 0;
  }
  .hero-upper-right {
    display: none;
  }
  .hero-lower-zone {
    grid-template-columns: 1fr;
  }
  .hero-lower-right-split {
    min-height: 180px;
  }
  .num-lower-black, .num-lower-neon {
    top: 0;
    right: 20px;
  }
  .editorial-section-header {
    grid-template-columns: 1fr;
  }
  .footer-editorial-grid {
    grid-template-columns: 1fr;
    gap: 36px;
  }
}

@media (max-width: 640px) {
  .triptych-banner {
    grid-template-columns: 1fr;
    height: auto;
  }
  .triptych-col {
    height: 130px;
    border-right: none;
    border-bottom: 2px solid #000;
  }
  .triptych-col:last-child {
    border-bottom: none;
  }
  .editorial-nav-strip {
    display: none;
  }
}

