/* ==========================================================================
   LIVE COUNTDOWN DOCK
   ========================================================================== */
.vst-countdown-dock {
  background: #061619;
  color: #FFFFFF;
  border-bottom: 2px solid rgba(139, 187, 146, 0.25);
  padding: 18px 0;
}

.vst-countdown-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  flex-wrap: wrap;
}

.vst-countdown-meta {
  display: flex;
  flex-direction: column;
}

.vst-cd-tag {
  font-family: var(--font-mono);
  font-size: 0.65rem;
  font-weight: 900;
  color: var(--vst-mint);
  letter-spacing: 0.08em;
}

.vst-cd-title {
  font-family: var(--font-syne);
  font-size: 1.1rem;
  font-weight: 900;
  color: #FFFFFF;
}

.vst-countdown-clock {
  display: flex;
  align-items: center;
  gap: 12px;
}

.vst-cd-unit {
  display: flex;
  flex-direction: column;
  align-items: center;
  background: #0B242A;
  color: var(--vst-mint);
  padding: 8px 14px;
  border-radius: 4px;
  border: 1.5px solid rgba(139, 187, 146, 0.3);
}

.vst-cd-val {
  font-family: var(--font-mono);
  font-size: 1.4rem;
  font-weight: 900;
  line-height: 1;
}

.vst-cd-lbl {
  font-family: var(--font-mono);
  font-size: 0.55rem;
  color: rgba(255, 255, 255, 0.6);
  letter-spacing: 0.08em;
  margin-top: 3px;
}

.vst-cd-divider {
  font-family: var(--font-mono);
  font-size: 1.4rem;
  font-weight: 900;
  color: var(--vst-jade);
}

.vst-cd-cta {
  background: var(--vst-jade);
  color: #FFFFFF;
  border: 1.5px solid var(--vst-mint);
}

.vst-cd-cta:hover {
  background: var(--vst-mint);
  color: var(--vst-teal-dark);
}

/* ==========================================================================
   GENERIC SECTION ARCHITECTURE (Dark-Themed Baseline)
   ========================================================================== */
.vst-section {
  padding: 100px 0;
  position: relative;
  border-bottom: 2px solid rgba(139, 187, 146, 0.25);
}

.vst-section-white { 
  background: #092328; 
  color: #FFFFFF; 
}

.vst-section-cobalt { 
  background: #061619; 
  color: #FFFFFF; 
}

.vst-section-magenta { 
  background: #092328; 
  color: #FFFFFF; 
}

.vst-section-black { 
  background: #040E10; 
  color: #FFFFFF; 
}

.vst-dot-pattern {
  background-image: radial-gradient(rgba(139, 187, 146, 0.12) 1.2px, transparent 1.2px);
  background-size: 28px 28px;
}

.vst-section-eyebrow-row {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 16px;
  flex-wrap: wrap;
}

.vst-badge-index {
  font-family: var(--font-mono);
  font-size: 0.72rem;
  font-weight: 900;
  letter-spacing: 0.1em;
  background: #051316;
  color: var(--vst-mint);
  padding: 4px 12px;
  border-radius: 2px;
  border: 1px solid rgba(139, 187, 146, 0.3);
}

.vst-badge-light { 
  background: var(--vst-teal-deep); 
  color: #FFFFFF; 
  border: 1px solid var(--vst-mint);
}

.vst-badge-dark { 
  background: var(--vst-jade); 
  color: #FFFFFF; 
}

.vst-badge-sub {
  font-family: var(--font-mono);
  font-size: 0.72rem;
  font-weight: 800;
  color: var(--vst-text-muted);
  letter-spacing: 0.08em;
}

.vst-badge-sub-light { color: rgba(255, 255, 255, 0.85); }
.vst-badge-sub-dark { color: rgba(255, 255, 255, 0.85); }

.vst-section-title {
  font-family: var(--font-display);
  font-size: clamp(2.6rem, 6.5vw, 5.2rem);
  font-weight: 900;
  line-height: 0.95;
  text-transform: uppercase;
  letter-spacing: -0.03em;
  color: #FFFFFF;
  margin-bottom: 24px;
}

.vst-title-light { color: #FFFFFF; }
.vst-title-dark { color: #FFFFFF; }
.vst-title-dot { color: var(--vst-mint); }

.vst-section-lead {
  font-size: 1.15rem;
  line-height: 1.65;
  color: var(--vst-text-muted);
  max-width: 760px;
  margin-bottom: 48px;
}

.vst-lead-light { color: rgba(255, 255, 255, 0.85); }

.vst-section-header-split {
  display: flex;
  justify-content: space-between;
  align-items: flex-end;
  gap: 40px;
  margin-bottom: 48px;
  flex-wrap: wrap;
}

/* ==========================================================================
   01 / MODULAR BENTO GRID (Dark Neo-Brutalist Architecture)
   ========================================================================== */
.vst-bento-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}

.vst-bento-card {
  border: 2px solid rgba(139, 187, 146, 0.3);
  border-radius: 6px;
  padding: 32px;
  box-shadow: 6px 6px 0px #02090B;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  transition: transform 0.15s ease, box-shadow 0.15s ease, border-color 0.15s ease;
}

.vst-bento-card:hover {
  transform: translate(-3px, -3px);
  box-shadow: 9px 9px 0px #02090B;
  border-color: var(--vst-mint);
}

.vst-bento-large {
  grid-column: span 2;
  background: #0B242A;
  color: #FFFFFF;
}

.vst-bento-magenta {
  background: var(--vst-teal-deep);
  color: #FFFFFF;
  border-color: var(--vst-jade);
}

.vst-bento-cyan {
  background: #0E332A;
  color: #FFFFFF;
  border-color: var(--vst-jade-bright);
}

.vst-bento-dark {
  grid-column: span 2;
  background: #051316;
  color: #FFFFFF;
  border-color: var(--vst-mint);
}

.vst-bento-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 16px;
}

.vst-bento-tag {
  font-family: var(--font-mono);
  font-size: 0.68rem;
  font-weight: 900;
  background: #040E10;
  color: var(--vst-mint);
  padding: 3px 8px;
  border-radius: 2px;
  border: 1px solid rgba(139, 187, 146, 0.3);
}

.vst-bento-meta {
  font-family: var(--font-mono);
  font-size: 0.7rem;
  font-weight: 800;
  color: var(--vst-text-muted);
}

.vst-bento-title {
  font-family: var(--font-syne);
  font-size: 1.6rem;
  font-weight: 900;
  margin-bottom: 12px;
  line-height: 1.2;
  color: #FFFFFF;
}

.vst-bento-body {
  font-size: 0.98rem;
  line-height: 1.6;
  color: var(--vst-text-muted);
  margin-bottom: 24px;
}

.vst-bento-stats-row {
  display: flex;
  gap: 24px;
  padding-top: 20px;
  border-top: 2px dashed rgba(139, 187, 146, 0.2);
}

.vst-mini-stat {
  display: flex;
  flex-direction: column;
}

.vst-mini-num {
  font-family: var(--font-display);
  font-size: 1.8rem;
  font-weight: 900;
  color: var(--vst-mint);
  line-height: 1;
}

.vst-mini-lbl {
  font-family: var(--font-mono);
  font-size: 0.72rem;
  font-weight: 700;
  color: rgba(255, 255, 255, 0.65);
}

.vst-bento-badge-tag {
  font-family: var(--font-mono);
  font-size: 0.75rem;
  font-weight: 900;
  background: #040E10;
  color: var(--vst-mint);
  padding: 8px 14px;
  border-radius: 3px;
  border: 1px solid rgba(139, 187, 146, 0.3);
  width: max-content;
}

.vst-bento-btn {
  background: var(--vst-mint);
  color: var(--vst-teal-dark);
  border-color: #092328;
}

.vst-bento-btn:hover {
  background: var(--vst-white);
}

/* ==========================================================================
   02 / THE THREE ARENAS (Dark Cards & High-Voltage Accents)
   ========================================================================== */
.vst-arenas-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}

.vst-arena-card {
  background: #0B242A;
  color: #FFFFFF;
  border: 2px solid rgba(139, 187, 146, 0.3);
  border-radius: 6px;
  padding: 32px 24px;
  box-shadow: 8px 8px 0px #02090B;
  display: flex;
  flex-direction: column;
  transition: transform 0.2s ease, box-shadow 0.2s ease, border-color 0.2s ease;
}

.vst-arena-card:hover {
  transform: translateY(-6px);
  box-shadow: 12px 12px 0px #02090B;
  border-color: var(--vst-mint);
}

.vst-arena-card-featured {
  border-top: 6px solid var(--vst-mint);
}

.vst-arena-top {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 20px;
}

.vst-arena-icon-wrap {
  width: 60px;
  height: 60px;
  background: #061619;
  border: 1px solid rgba(139, 187, 146, 0.25);
  border-radius: 4px;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 8px;
}

.vst-arena-mascot {
  width: 100%;
  height: 100%;
  object-fit: contain;
}

.vst-arena-number {
  font-family: var(--font-mono);
  font-size: 0.78rem;
  font-weight: 900;
  background: #061619;
  border: 1px solid rgba(139, 187, 146, 0.3);
  color: #FFFFFF;
  padding: 4px 10px;
  border-radius: 3px;
}

.vst-num-accent {
  background: var(--vst-mint);
  color: var(--vst-teal-dark);
}

.vst-arena-title {
  font-family: var(--font-display);
  font-size: 1.5rem;
  font-weight: 900;
  line-height: 1.2;
  margin-bottom: 12px;
  color: #FFFFFF;
}

.vst-arena-desc {
  font-size: 0.95rem;
  line-height: 1.55;
  color: var(--vst-text-muted);
  margin-bottom: 24px;
