  padding: 100px 0;
  position: relative;
  border-bottom: var(--vst-border-thick);
}

.vst-section-white { background: #FFFFFF; color: var(--vst-teal-dark); }
.vst-section-cobalt { background: var(--vst-teal-deep); color: #FFFFFF; }
.vst-section-magenta { background: var(--vst-jade); color: #FFFFFF; }
.vst-section-black { background: var(--vst-teal-dark); color: #FFFFFF; }

.vst-section-eyebrow-row {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 16px;
  flex-wrap: wrap;
}

.vst-badge-index {
  font-family: var(--font-mono);
  font-size: 0.72rem;
  font-weight: 900;
  letter-spacing: 0.1em;
  background: var(--vst-teal-dark);
  color: #FFFFFF;
  padding: 4px 12px;
  border-radius: 2px;
}

.vst-badge-light { background: #FFFFFF; color: var(--vst-teal-dark); }
.vst-badge-dark { background: var(--vst-mint); color: var(--vst-teal-dark); }

.vst-badge-sub {
  font-family: var(--font-mono);
  font-size: 0.72rem;
  font-weight: 800;
  color: var(--vst-muted);
  letter-spacing: 0.08em;
}

.vst-badge-sub-light { color: rgba(255, 255, 255, 0.85); }
.vst-badge-sub-dark { color: rgba(255, 255, 255, 0.85); }

.vst-section-title {
  font-family: var(--font-display);
  font-size: clamp(2.6rem, 6.5vw, 5.2rem);
  font-weight: 900;
  line-height: 0.95;
  text-transform: uppercase;
  letter-spacing: -0.03em;
  color: var(--vst-teal-dark);
  margin-bottom: 24px;
}

.vst-title-light { color: #FFFFFF; }
.vst-title-dark { color: #FFFFFF; }
.vst-title-dot { color: var(--vst-mint); }

.vst-section-lead {
  font-size: 1.15rem;
  line-height: 1.65;
  color: #334155;
  max-width: 760px;
  margin-bottom: 48px;
}

.vst-lead-light { color: rgba(255, 255, 255, 0.85); }

.vst-section-header-split {
  display: flex;
  justify-content: space-between;
  align-items: flex-end;
  gap: 40px;
  margin-bottom: 48px;
  flex-wrap: wrap;
}

/* ==========================================================================
   01 / MODULAR BENTO GRID (Original Architecture)
   ========================================================================== */
.vst-bento-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}

.vst-bento-card {
  border: var(--vst-border-thick);
  border-radius: 6px;
  padding: 32px;
  box-shadow: var(--vst-shadow-md);
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  transition: transform 0.15s ease, box-shadow 0.15s ease;
}

.vst-bento-card:hover {
  transform: translate(-3px, -3px);
  box-shadow: var(--vst-shadow-lg);
}

.vst-bento-large {
  grid-column: span 2;
  background: #FFFFFF;
}

.vst-bento-magenta {
  background: var(--vst-teal-deep);
  color: #FFFFFF;
}

.vst-bento-cyan {
  background: var(--vst-jade);
  color: #FFFFFF;
}

.vst-bento-dark {
  grid-column: span 2;
  background: var(--vst-teal-dark);
  color: #FFFFFF;
  border-color: var(--vst-mint);
}

.vst-bento-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 16px;
}

.vst-bento-tag {
  font-family: var(--font-mono);
  font-size: 0.68rem;
  font-weight: 900;
  background: var(--vst-teal-dark);
  color: #FFFFFF;
  padding: 3px 8px;
  border-radius: 2px;
}

.vst-bento-meta {
  font-family: var(--font-mono);
  font-size: 0.7rem;
  font-weight: 800;
  opacity: 0.75;
}

.vst-bento-title {
  font-family: var(--font-syne);
  font-size: 1.6rem;
  font-weight: 900;
  margin-bottom: 12px;
  line-height: 1.2;
}

.vst-bento-body {
  font-size: 0.98rem;
  line-height: 1.6;
  margin-bottom: 24px;
}

.vst-bento-stats-row {
  display: flex;
  gap: 24px;
  padding-top: 20px;
  border-top: 2px dashed rgba(9, 35, 40, 0.15);
}

.vst-mini-stat {
  display: flex;
  flex-direction: column;
}

.vst-mini-num {
  font-family: var(--font-display);
  font-size: 1.8rem;
  font-weight: 900;
  color: var(--vst-jade);
  line-height: 1;
}

.vst-mini-lbl {
  font-family: var(--font-mono);
  font-size: 0.72rem;
  font-weight: 700;
  color: var(--vst-muted);
}

.vst-bento-badge-tag {
  font-family: var(--font-mono);
  font-size: 0.75rem;
  font-weight: 900;
  background: var(--vst-teal-dark);
  color: var(--vst-mint);
  padding: 8px 14px;
  border-radius: 3px;
  width: max-content;
}

.vst-bento-btn {
  background: var(--vst-mint);
  color: var(--vst-teal-dark);
  border-color: #092328;
}

/* ==========================================================================
   02 / THE THREE ARENAS
   ========================================================================== */
.vst-arenas-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}

.vst-arena-card {
  background: #FFFFFF;
  color: var(--vst-teal-dark);
  border: var(--vst-border-thick);
  border-radius: 6px;
  padding: 32px 24px;
  box-shadow: var(--vst-shadow-xl);
  display: flex;
  flex-direction: column;
  transition: transform 0.2s ease, box-shadow 0.2s ease;
}

.vst-arena-card:hover {
  transform: translateY(-6px);
