  align-items: center;
  margin-bottom: 20px;
}

.vst-arena-icon-wrap {
  width: 60px;
  height: 60px;
  background: var(--vst-teal-dark);
  border-radius: 4px;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 8px;
}

.vst-arena-mascot {
