  height: 100%;
  object-fit: contain;
}

.vst-arena-number {
  font-family: var(--font-mono);
  font-size: 0.78rem;
  font-weight: 900;
  background: #F1F5F9;
  border: 1.5px solid #092328;
  padding: 4px 10px;
