}

.vst-arena-title {
  font-family: var(--font-display);
  font-size: 1.5rem;
  font-weight: 900;
  line-height: 1.2;
  margin-bottom: 12px;
}

.vst-arena-desc {
  font-size: 0.95rem;
  line-height: 1.55;
  color: #334155;
  margin-bottom: 24px;
  flex: 1;
}

.vst-arena-chips {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-bottom: 20px;
}

.vst-chip {
  font-family: var(--font-mono);
  font-size: 0.72rem;
