/* Scoreboard Card */
.vst-scoreboard-card {
  background: #051316;
  color: #FFFFFF;
  border: 2.5px solid var(--vst-mint);
  padding: 32px;
  box-shadow: 10px 10px 0px #02090B;
  position: sticky;
  top: 90px;
}

.vst-score-top {
  text-align: center;
  padding-bottom: 24px;
  border-bottom: 2px solid rgba(139, 187, 146, 0.2);
}

.vst-score-tag {
  font-family: var(--font-mono);
  font-size: 0.72rem;
  font-weight: 900;
  letter-spacing: 0.1em;
  color: var(--vst-mint);
}

.vst-score-number {
  font-family: var(--font-display);
  font-size: 4.6rem;
  font-weight: 900;
  line-height: 1;
  margin: 6px 0;
  color: var(--vst-mint);
}

.vst-score-out {
  font-family: var(--font-mono);
  font-size: 0.85rem;
  color: rgba(255, 255, 255, 0.6);
}

.vst-score-tier-badge {
  font-family: var(--font-display);
  font-size: 0.95rem;
  font-weight: 900;
  letter-spacing: 0.05em;
  text-align: center;
  background: var(--vst-jade);
  color: #FFFFFF;
  padding: 8px;
  margin: 20px 0;
  border-radius: 2px;
}

.vst-score-breakdown {
  display: flex;
  flex-direction: column;
  gap: 8px;
  font-family: var(--font-mono);
  font-size: 0.85rem;
  margin-bottom: 20px;
}

.vst-breakdown-row {
  display: flex;
  justify-content: space-between;
  padding: 6px 0;
  border-bottom: 1px dashed rgba(139, 187, 146, 0.2);
}

.vst-score-advice {
