  font-style: italic;
  padding: 12px;
  background: rgba(139, 187, 146, 0.1);
  border-left: 3px solid var(--vst-mint);
}

/* ==========================================================================
   05 / 48-HOUR SCHEDULE
   ========================================================================== */
.vst-schedule-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 30px;
}

.vst-schedule-day {
  background: #081B1F;
  border: 2px solid rgba(139, 187, 146, 0.25);
  padding: 24px;
  box-shadow: 8px 8px 0px rgba(0, 0, 0, 0.6);
}

.vst-day-header {
  font-family: var(--font-display);
  font-size: 1.3rem;
  font-weight: 900;
  color: var(--vst-mint);
  padding-bottom: 16px;
  margin-bottom: 20px;
  border-bottom: 2px solid rgba(139, 187, 146, 0.2);
}

.vst-schedule-item {
  display: flex;
  gap: 16px;
  padding: 16px 12px;
  border-bottom: 1px solid rgba(139, 187, 146, 0.1);
  transition: transform 0.15s ease;
}

.vst-schedule-item:hover {
  transform: translateX(4px);
}

.vst-sch-featured {
  background: rgba(42, 131, 95, 0.25);
  border-left: 4px solid var(--vst-mint);
}

.vst-sch-time {
  font-family: var(--font-mono);
  font-size: 1.1rem;
  font-weight: 900;
  color: var(--vst-mint);
  width: 65px;
  flex-shrink: 0;
}

.vst-sch-title {
  display: block;
  font-family: var(--font-syne);
  font-size: 0.95rem;
  font-weight: 800;
  color: #FFFFFF;
  margin-bottom: 4px;
}

.vst-sch-sub {
  font-size: 0.82rem;
  color: rgba(255, 255, 255, 0.65);
  line-height: 1.4;
}

