  font-family: var(--font-mono);
  font-size: 0.75rem;
  color: var(--vst-muted);
}

.vst-presets-row {
  display: flex;
  gap: 10px;
  margin-top: 8px;
  flex-wrap: wrap;
}

.vst-preset-chip {
  font-family: var(--font-mono);
  font-size: 0.75rem;
  font-weight: 800;
  background: #F1F5F9;
  border: 2px solid #092328;
  padding: 8px 16px;
  border-radius: 3px;
  cursor: pointer;
  transition: all 0.15s ease;
}

.vst-preset-chip:hover {
  background: var(--vst-jade);
  color: #FFFFFF;
}

/* Scoreboard Card */
.vst-scoreboard-card {
  background: var(--vst-teal-dark);
  color: #FFFFFF;
  border: 3px solid var(--vst-mint);
  padding: 32px;
  box-shadow: 10px 10px 0px var(--vst-jade);
  position: sticky;
  top: 90px;
}

.vst-score-top {
  text-align: center;
  padding-bottom: 24px;
  border-bottom: 2px solid rgba(139, 187, 146, 0.2);
}

.vst-score-tag {
  font-family: var(--font-mono);
  font-size: 0.72rem;
  font-weight: 900;
  letter-spacing: 0.1em;
  color: var(--vst-mint);
}

.vst-score-number {
  font-family: var(--font-display);
  font-size: 4.6rem;
  font-weight: 900;
  line-height: 1;
  margin: 6px 0;
  color: var(--vst-mint);
}

.vst-score-out {
  font-family: var(--font-mono);
  font-size: 0.85rem;
  color: rgba(255, 255, 255, 0.6);
}

.vst-score-tier-badge {
  font-family: var(--font-display);
  font-size: 0.95rem;
  font-weight: 900;
  letter-spacing: 0.05em;
  text-align: center;
  background: var(--vst-jade);
  color: #FFFFFF;
  padding: 8px;
  margin: 20px 0;
  border-radius: 2px;
}

.vst-score-breakdown {
  display: flex;
  flex-direction: column;
  gap: 8px;
  font-family: var(--font-mono);
  font-size: 0.85rem;
  margin-bottom: 20px;
}

.vst-breakdown-row {
  display: flex;
  justify-content: space-between;
  padding: 6px 0;
  border-bottom: 1px dashed rgba(139, 187, 146, 0.2);
}

.vst-score-advice {
  font-size: 0.85rem;
  line-height: 1.5;
  color: rgba(255, 255, 255, 0.8);
  font-style: italic;
  padding: 12px;
  background: rgba(139, 187, 146, 0.1);
  border-left: 3px solid var(--vst-mint);
}

/* ==========================================================================
   05 / 48-HOUR SCHEDULE
   ========================================================================== */
.vst-schedule-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 30px;
}

.vst-schedule-day {
  background: #081B1F;
  border: 2px solid rgba(139, 187, 146, 0.25);
  padding: 24px;
  box-shadow: 8px 8px 0px rgba(0, 0, 0, 0.6);
}

.vst-day-header {
  font-family: var(--font-display);
  font-size: 1.3rem;
  font-weight: 900;
  color: var(--vst-mint);
  padding-bottom: 16px;
  margin-bottom: 20px;
  border-bottom: 2px solid rgba(139, 187, 146, 0.2);
}

.vst-schedule-item {
  display: flex;
  gap: 16px;
  padding: 16px 12px;
  border-bottom: 1px solid rgba(139, 187, 146, 0.1);
  transition: transform 0.15s ease;
}

.vst-schedule-item:hover {
  transform: translateX(4px);
}

.vst-sch-featured {
  background: rgba(42, 131, 95, 0.25);
  border-left: 4px solid var(--vst-mint);
}

.vst-sch-time {
  font-family: var(--font-mono);
  font-size: 1.1rem;
  font-weight: 900;
  color: var(--vst-mint);
  width: 65px;
  flex-shrink: 0;
}

.vst-sch-title {
  display: block;
  font-family: var(--font-syne);
  font-size: 0.95rem;
  font-weight: 800;
  color: #FFFFFF;
  margin-bottom: 4px;
}

.vst-sch-sub {
  font-size: 0.82rem;
  color: rgba(255, 255, 255, 0.65);
  line-height: 1.4;
}

/* ==========================================================================
   06 / PRIZES & SEED GRANTS
   ========================================================================== */
.vst-prizes-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
  margin-bottom: 30px;
}

.vst-prize-box {
  background: #FFFFFF;
  color: var(--vst-teal-dark);
  border: var(--vst-border-thick);
  padding: 32px 24px;
  box-shadow: var(--vst-shadow-xl);
  text-align: center;
  transition: transform 0.2s ease, box-shadow 0.2s ease;
}

.vst-prize-box:hover {
  transform: translateY(-6px);
  box-shadow: 14px 14px 0px #092328;
}

.vst-prize-gold { border-top: 8px solid var(--vst-gold); }
.vst-prize-silver { border-top: 8px solid #94A3B8; }
.vst-prize-bronze { border-top: 8px solid #CD7F32; }

.vst-prize-rank {
  font-family: var(--font-mono);
  font-size: 0.72rem;
  font-weight: 900;
  letter-spacing: 0.1em;
  background: var(--vst-teal-dark);
  color: #FFFFFF;
  padding: 3px 8px;
  border-radius: 2px;
  display: inline-block;
  margin-bottom: 12px;
}

.vst-prize-name {
  font-family: var(--font-display);
  font-size: 1.35rem;
  font-weight: 900;
  margin-bottom: 12px;
}

.vst-prize-pool {
  font-family: var(--font-display);
  font-size: 1.7rem;
  font-weight: 900;
  color: var(--vst-jade);
  line-height: 1.1;
  margin-bottom: 6px;
}

.vst-prize-tag {
  display: block;
  font-family: var(--font-mono);
  font-size: 0.75rem;
  font-weight: 800;
  color: var(--vst-muted);
  text-transform: uppercase;
  margin-bottom: 24px;
  padding-bottom: 16px;
  border-bottom: 1.5px dashed rgba(9, 35, 40, 0.2);
}

.vst-prize-list {
  list-style: none;
  text-align: left;
  display: flex;
  flex-direction: column;
  gap: 10px;
  font-size: 0.88rem;
  font-weight: 600;
}

.vst-prize-list li::before {
  content: '◆ ';
  color: var(--vst-jade);
}

