/* ==========================================================================
   VISTAARA 2026 — OFFICIAL GOTHAM DARK DESIGN SYSTEM
   Monolithic Noir & Industrial Brutalism:
   - Pitch Void Black: #080808 / #050505
   - Matte Obsidian Canvas: #0A0A0A
   - Industrial Graphite Cards: #121214 / #18181B
   - Cold Zinc Steel Borders: #27272A / #3F3F46
   - Gotham Signal Tungsten Amber: #F59E0B / #FBBF24
   - Cold Platinum & White Text: #FFFFFF / #E4E4E7 / #A1A1AA
   ========================================================================== */

:root {
  /* Gotham Dark Palette Tokens */
  --vst-black-void: #050505;        /* Absolute pitch void */
  --vst-black-surface: #0A0A0A;     /* Primary Gotham canvas */
  --vst-teal-dark: #0A0A0A;         /* Primary surface token */
  --vst-teal-deep: #141416;         /* Elevated card surface */
  --vst-teal-mid: #1E1E22;          /* Intermediate panel */
  --vst-jade: #F59E0B;              /* Gotham Signal Tungsten Amber */
  --vst-jade-bright: #FBBF24;       /* Highlight Amber */
  --vst-mint: #F59E0B;              /* Primary Signal Light */
  --vst-mint-light: #FDE68A;        /* Warm Gold Tint */
  --vst-mint-pale: #1C1917;         /* Amber Dark Surface */

  --vst-black: #050505;
  --vst-obsidian: #080808;          /* Background surface */
  --vst-card-dark: #121214;         /* Primary card */
  --vst-card-darker: #0C0C0E;       /* Inset panel */
  --vst-dark-gray: #18181B;         /* Control panel */
  --vst-white: #FFFFFF;
  --vst-cream: #121214;             /* Dark panel */
  --vst-text-muted: #A1A1AA;        /* Cold Zinc text */
  --vst-muted: #71717A;             /* Muted graphite */
  --vst-border-dim: #27272A;
  --vst-gold: #F59E0B;

  /* Neo-brutalist structural tokens */
  --vst-border-main: 1.5px solid #27272A;
  --vst-border-thick: 2px solid #27272A;
  --vst-border-white: 1.5px solid #3F3F46;
  --vst-shadow-sm: 3px 3px 0px #000000;
  --vst-shadow-md: 5px 5px 0px #000000;
  --vst-shadow-lg: 8px 8px 0px #000000;
  --vst-shadow-xl: 12px 12px 0px #000000;
  --vst-shadow-jade: 5px 5px 0px #000000;
  --vst-shadow-mint: 5px 5px 0px #000000;
  --vst-shadow-white: 5px 5px 0px #27272A;

  /* Typography */
  --font-display: 'Archivo Black', -apple-system, BlinkMacSystemFont, sans-serif;
  --font-syne: 'Syne', sans-serif;
  --font-mono: 'Space Mono', SFMono-Regular, Consolas, monospace;
  --font-body: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;

  --site-max-width: 1320px;
}

