/* Mobile Drawer */
.vst-mobile-drawer {
  position: fixed;
  top: 74px;
  left: 20px;
  right: 20px;
  background: #121214;
  border: 1.5px solid #27272A;
  border-radius: 8px;
  padding: 24px;
  display: none;
  flex-direction: column;
  gap: 14px;
  z-index: 89999;
  box-shadow: 0 16px 40px rgba(0, 0, 0, 0.95);
}

.vst-mobile-drawer.open {
  display: flex;
}

.vst-mobile-drawer .mobile-nav-link {
  font-family: var(--font-mono);
  font-size: 0.95rem;
  font-weight: 800;
  color: var(--vst-white);
  padding: 8px 0;
  border-bottom: 1px solid #27272A;
}

/* ==========================================================================
   HERO SECTION — Monolithic Gotham Dark (#0A0A0A) & Tungsten Amber (#F59E0B)
   ========================================================================== */
.vst-hero {
  position: relative;
  min-height: 100vh;
  background: var(--vst-teal-dark);
  color: var(--vst-white);
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  padding: 140px 24px 70px 24px;
  overflow: hidden;
  border-bottom: var(--vst-border-thick);
}

.vst-hero-grid-bg {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background-image: 
    linear-gradient(to right, rgba(255, 255, 255, 0.05) 1px, transparent 1px),
    linear-gradient(to bottom, rgba(255, 255, 255, 0.05) 1px, transparent 1px);
  background-size: 40px 40px;
  pointer-events: none;
}

/* Proprietary Artifact 1: Flying Mascot Sticker */
.vst-artifact-mascot {
  position: absolute;
  top: 135px;
  left: 5%;
  z-index: 10;
  display: flex;
  flex-direction: column;
  align-items: center;
  user-select: none;
  filter: drop-shadow(6px 6px 0px #000000);
  transform: rotate(-6deg);
  transition: transform 0.2s ease;
}

.vst-artifact-mascot:hover {
  transform: rotate(0deg) scale(1.08);
}

.vst-mascot-img {
  width: 110px;
  height: auto;
  object-fit: contain;
}

.vst-mascot-badge {
  font-family: var(--font-mono);
  font-size: 0.65rem;
  font-weight: 900;
  background: #18181B;
  color: var(--vst-mint);
  padding: 4px 10px;
  border: 1.5px solid var(--vst-mint);
  border-radius: 3px;
  margin-top: -8px;
}

/* Proprietary Artifact 2: Floating Lanyard Pass Tag */
.vst-artifact-pass {
  position: absolute;
  top: 140px;
  right: 5%;
  z-index: 10;
  user-select: none;
  cursor: pointer;
  transform: rotate(5deg);
  filter: drop-shadow(6px 6px 0px #000000);
  transition: transform 0.2s ease;
}

.vst-artifact-pass:hover {
  transform: rotate(0deg) scale(1.06);
}

.vst-pass-clip {
  width: 36px;
  height: 14px;
  background: #18181B;
  border: 1.5px solid #3F3F46;
  border-radius: 4px 4px 0 0;
  margin: 0 auto;
}

.vst-pass-inner {
  background: #0C0C0E;
  color: #FFFFFF;
  border: 1.5px solid #3F3F46;
  padding: 16px 20px;
  border-radius: 4px;
  text-align: center;
}

