  border: 2px solid rgba(139, 187, 146, 0.25);
  box-shadow: 6px 6px 0px #02090B;
  transition: transform 0.15s ease, box-shadow 0.15s ease, border-color 0.15s ease;
  border-radius: 4px;
}

.faq-item:hover {
  transform: translate(-2px, -2px);
  box-shadow: 8px 8px 0px #02090B;
  border-color: var(--vst-mint);
}

.faq-question-btn {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 22px 24px;
  text-align: left;
  font-family: var(--font-syne);
  font-size: 1.15rem;
  font-weight: 800;
  color: #FFFFFF;
  gap: 16px;
  cursor: pointer;
}

.gc-faq-answer {
  display: none;
  padding: 0 24px 24px 24px;
  font-size: 1rem;
  line-height: 1.65;
  color: var(--vst-text-muted);
  border-top: 1.5px dashed rgba(139, 187, 146, 0.2);
  margin-top: 4px;
  padding-top: 16px;
}

